window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q05"]=window.__LIBQ["the-gioi-hoan-my"]["q05"]||{};window.__LIBQ["the-gioi-hoan-my"]["q05"]["cotTruyen"]=[{"chuong":401,"tieuDe":"Không Gì Địch Nổi","tomTat":"Thạch Hạo công khai trừng trị thanh niên có liên hệ với Bất Lão sơn, đánh gãy răng rồi ném hắn khỏi cung điện, đồng thời dùng khí thế và một hơi thổi đánh tan nhóm người xông tới cứu viện. Bất chấp lời cảnh báo của Thiên Thiên quận chúa về truyền thừa bất hủ này, nó không hề có ý định trốn tránh vì biết các Tôn giả đang ẩn mình để tránh đại kiếp. Một thanh niên mang Hoàng huyết Vũ tộc định luận bàn nhưng vừa cảm nhận sát khí của Thạch Hạo đã tự nhận không địch nổi và chủ động rời đi. Khi thiên tài Hắc Vân tộc tới trả thù, Thạch Hạo niêm phong đại điện bằng khí thế rồi chỉ tiến ba bước đã ép đối phương thổ huyết, trọng thương và bay khỏi cung điện. Sức mạnh áp đảo ấy khiến mọi người nghi ngờ thiếu niên vô danh chính là Thạch Hạo tái xuất, khiến tin đồn nhanh chóng lan khắp Hoàng Đô Hỏa quốc. Vài ngày sau, Hỏa Linh Nhi xuất quan và mở tiệc tại biệt viện hoàng gia, thu hút người của Bất Lão sơn, Tây Thiên giáo, Tiệt Thiên giáo cùng nhiều cường giả vực ngoại, báo hiệu một trận phong ba lớn sắp nổi lên."},{"chuong":402,"tieuDe":"Quần Hùng Tập Trung","tomTat":"Thạch Hạo vượt qua tiểu truyền tống trận để tiến vào biệt viện tại Hoàng Đô Hỏa quốc, nơi cường giả Hoang Vực và vực ngoại cùng tụ hội, giao lưu bảo vật và âm thầm dò xét lẫn nhau. Hắn lần lượt nhận ra người của Tiểu Tây Thiên, Bạch Hổ nhất mạch và Viêm Mãng tộc; đại diện Viêm Mãng tộc còn chất vấn Hỏa quốc về thiên tài đã chết trong tổ địa, nhưng bị bác lại bằng quy tắc sinh tử được các bên chấp thuận từ trước. Khi Tinh Thần thảo trong vườn nhú chiếc lá thứ bảy, đám đông từ chuyện linh dược và bảo thuật Côn Bằng chuyển sang bàn luận số phận của Thạch Hạo, Thạch Nghị, đồng thời nghi ngờ thiếu niên gây náo động gần đây chính là Thạch Hạo. Người của Bất Lão sơn lập tức tuyên bố sẽ bảo vệ uy nghiêm đạo thống và trấn áp kẻ xúc phạm họ, song Thạch Hạo đang ẩn mình giữa đám đông chỉ thản nhiên bỏ ngoài tai. Sau khi Đại Hồng Điểu lén rời khỏi tay áo hắn, Vân Hi cùng nhiều sinh linh thuần huyết xuất hiện, còn Cửu đầu sư tử tái ngộ Hỏa Linh Nhi với huyết thống đã gần tiến hóa thành Hoàng kim sư tử thuần huyết. Biết Cửu đầu sư tử từng kết bái với Thạch Hạo, một kẻ giữa đám đông ngang nhiên tuyên bố muốn bắt nó làm tọa kỵ, vừa ham huyết thống quý giá vừa cố tình mượn huynh đệ của hắn để làm nhục hắn."},{"chuong":403,"tieuDe":"Cầm Thú Đại Phát Thần Uy","tomTat":"Các thiên tài Hắc Vân tộc muốn rửa mối nhục từng chịu dưới tay Thạch Hạo nên khiêu khích Cửu đầu sư tử, nhưng kẻ xuất chiến đầu tiên lập tức bị Sư Tử hống đánh trọng thương. Cửu đầu sư tử sau đó chủ động nhận lời quyết đấu với thiên tài mạnh nhất của đối phương trên võ đài nổi do Hỏa Linh Nhi cho người dựng lên. Sau hơn trăm hiệp giao tranh, thiên tài Hắc Vân tộc hóa thành kiếp vân, dẫn động sấm chớp, song vẫn bị sát trận do chín ký hiệu của Cửu đầu sư tử hợp thành phá tan và giết chết giữa không trung. Đại Hồng Điểu tiếp đó xuất hiện chế giễu Hắc Vân tộc rồi bị một con trâu đỏ truy sát, nhưng nó đã dùng thanh kiếm gãy được Thạch Hạo giao cho để chém đôi đối thủ. Những chiến thắng liên tiếp của hai người đồng hành khiến các cường giả trong trang viên càng kiêng dè Thạch Hạo dù hắn vẫn chưa công khai lộ diện. Cuối cùng, một người trung niên của Bất Lão sơn tuyên bố sẽ nghiêm trị Thạch Hạo vì hắn đã làm bị thương con cháu của thế lực này, mở ra một cuộc đối đầu mới."},{"chuong":404,"tieuDe":"\"Người Thân\" Bất Lão Sơn","tomTat":"Một Vương giả Liệt Trận cảnh của Bất Lão sơn xuất hiện tại cuộc tụ hội ở Hỏa quốc, ngang nhiên đòi bắt Đại Hồng Điểu và Cửu đầu sư tử vì chúng có quan hệ với Thạch Hạo. Đại Hồng Điểu lên tiếng chế giễu, còn Cửu đầu sư tử dùng sát trận do chín ký hiệu màu vàng hợp thành để chống lại phù quang trấn áp của đối phương. Theo lời thỉnh cầu của Hỏa Linh Nhi, Vương thúc của nàng đứng ra hòa giải nhưng bị người Bất Lão sơn thẳng thừng bác bỏ, khiến các cao thủ Hỏa quốc phẫn nộ. Đại Hồng Điểu liền trao kiếm gãy màu đen cho Cửu đầu sư tử, giúp nó phát ra kiếm khí sắc bén và ép Vương giả có cảnh giới cao hơn phải liên tục né tránh. Khi thần lực của Cửu đầu sư tử dần cạn kiệt, người trung niên chớp thời cơ áp sát để trấn áp nó. Đúng lúc ấy, hai luồng kiếm khí bí ẩn bất ngờ chém ra từ hư không, một luồng suýt cắt ngang eo và luồng còn lại chặt đứt cánh tay của Vương giả Bất Lão sơn, khiến toàn trường chết lặng."},{"chuong":405,"tieuDe":"Thạch Hạo Tái Hiện","tomTat":"Ẩn mình ngoài xa, Thạch Hạo lần đầu thi triển kiếm ý lĩnh ngộ từ tấm da thú, phóng kiếm khí xuyên hư không chém đứt cánh tay của cường giả Liệt Trận thuộc Bất Lão sơn, nhưng không hạ sát vì chưa xác minh quan hệ huyết thống giữa thế lực này với mẹ mình. Cửu đầu sư tử thừa cơ dùng kiếm gãy đánh đối phương bị thương thêm, buộc hắn cùng những người Bất Lão sơn phải tạm thời rút lui. Tại khu giao dịch, nhờ Tiểu tháp chỉ dẫn và Trùng Đồng quan sát, Thạch Hạo dùng một viên bảo châu Bắc Hải đổi lấy tảng Địa Hỏa thạch tưởng như bình thường, bên trong thực chất là Thái Dương thạch đỉnh cấp chứa kiếm ý đáng sợ. Khi vài tu sĩ trẻ nhận ra Thạch Hạo, tin tiểu Thạch mất tích hơn một năm rưỡi đã tái hiện lập tức khiến cả trang viên sôi trào. Một lão già Liệt Trận của Hắc Vân tộc tìm đến trả thù nhưng bị Thạch Hạo đánh nổ cánh tay chỉ trong một đòn, khiến Vương giả rắn đỏ và cường giả Viêm Mãng tộc đều không dám manh động. Người trung niên Bất Lão sơn quay lại cùng một ông lão và dùng uy danh cổ giáo đe dọa, song Thạch Hạo chẳng những không lùi mà còn áp sát, chỉ bằng khí thế đã ép vị Vương giả kia phun máu và trọng thương trước sự kinh hãi của mọi người."},{"chuong":406,"tieuDe":"Chém Vương","tomTat":"Sau một năm rưỡi biến mất, Thạch Hạo công khai tái hiện, chỉ bằng khí thế và tràng vực thân thể đã khiến người trung niên cụt tay của Bất Lão sơn trọng thương. Tần Thủ Thành vừa khen ngợi thiên tư của nó vừa trách nó sát khí quá nặng, nhưng Thạch Hạo lại cảm nhận được sát ý kín đáo và nghi ngờ những người này có quan hệ huyết thống với mình từ phía mẹ. Một Vương giả Viêm Mãng tộc bất ngờ đứng ra báo thù cho hậu nhân từng bị giết tại tổ địa Hỏa tộc, dùng bốn trận kỳ dựng sát trận Tứ Tượng hòng luyện hóa thiếu niên. Thạch Hạo đã tiến vào Liệt Trận cảnh nên bình an phá vây, bất ngờ bóp cổ đối thủ rồi dứt khoát chém đầu ngay trước quần hùng. Nó thu bản thể Viêm Mãng khổng lồ làm bảo dược huyết nhục, còn Đại Hồng Điểu công khai xem chiến lợi phẩm ấy như nguyên liệu cho một bữa ăn. Khi đông đảo tu sĩ Bất Lão sơn cùng thanh niên tóc tím từng bị nó đánh trọng thương kéo đến, Thạch Hạo bình tĩnh đối diện, chuẩn bị hỏi rõ tung tích cha mẹ và mối liên hệ giữa mình với thế lực này."},{"chuong":407,"tieuDe":"Ngang Tàn Tới Cùng","tomTat":"Tần Siêu dựa vào thân phận hậu nhân Bất Lão sơn cùng các cao thủ trong tộc để trả mối nhục từng bị Thạch Hạo bạt tai, nhưng Thạch Hạo phớt lờ hắn, còn Đại Hồng Điểu công khai chế giễu khiến hắn càng thêm tức tối. Trước sức ép của Tần Thủ Thành, Thạch Hạo nhận ra vị trưởng lão này vẫn mang sát ý dù biết đôi bên có thể tồn tại quan hệ huyết thống, từ đó nghi ngờ Bất Lão sơn đang che giấu nội tình. Khi Tần Siêu liên tục thúc giục giết mình, Thạch Hạo thi triển thân pháp Côn Bằng áp sát nhanh đến mức các cao thủ không kịp ngăn cản, đánh nát nửa mặt rồi hủy gân mạch và phế sạch tu vi của hắn. Thạch Hạo tạm tha mạng Tần Siêu vì chưa xác định rõ mối liên hệ giữa bản thân với Bất Lão sơn, song hành động ngang tàng ấy vẫn khiến những người tại hiện trường chấn động. Bị người trung niên cụt tay chất vấn, nó tuyên bố ngay cả Tôn giả của Bổ Thiên giáo cũng từng dám chém nên tuyệt nhiên không sợ trở thành kẻ địch của Bất Lão sơn. Cuối cùng, Thạch Hạo bác bỏ yêu cầu nhận lỗi, chịu trói và theo Tần Thủ Thành về thánh sơn, đồng thời quyết định tự mình xem Bất Lão sơn sẽ đối xử ra sao nếu giữa hai bên thực sự có quan hệ máu mủ."},{"chuong":408,"tieuDe":"Vòng Ngũ Hành","tomTat":"Tần Thủ Thành lấy danh nghĩa Bất Lão sơn kết tội Thạch Hạo và kêu gọi quần hùng trừng trị nó, nhưng chỉ có lão già Hắc Vân tộc cùng Vương giả Hỏa Ngưu tộc hưởng ứng. Lão tế ra Vòng Ngũ Hành hàng nhái, phong tỏa cả đình viện rồi thả những người ngoài cuộc, chỉ giữ lại Thạch Hạo, Cửu đầu sư tử và Đại Hồng Điểu. Mọi người nhận ra đây là bản mô phỏng không trọn vẹn của bảo vật trấn giáo Bất Lão sơn, song nó vẫn có thể giam cầm thân thể, chân nguyên và trấn áp Vương giả. Dù không thể cử động, Thạch Hạo vẫn vận dụng kiếm ý xuyên thủng ngực lão già Hắc Vân tộc, sau đó phát kiếm khí từ gân mạch và khiếu huyệt để chống lại đòn đánh lén của Hỏa Ngưu Vương. Tần Thủ Thành tiếp tục ép chiếc vòng phong tỏa hư không rồi dùng lôi phù giáng xuống, định phế bỏ tu vi của Thạch Hạo, trong khi người ngoài khó thể cứu viện vì bảo cụ có thể hấp thu và phân giải ngoại lực. Giữa biển sấm sét, toàn thân Thạch Hạo phát sáng, cốt văn thần bí liên tục hiện lên và nó tuyên bố sẽ tự mình phá vỡ trạng thái giam cầm."},{"chuong":409,"tieuDe":"Tư Thế Vô Địch","tomTat":"Bị vòng Ngũ Hành cùng ba Vương giả hợp lực trấn áp, Thạch Hạo vận chuyển pháp môn Côn Bằng, diễn hóa côn ngư và chim bằng để dùng hai khí âm dương trung hòa tinh khí ngũ hành, giành lại thế chủ động. Hắn thi triển kiếm ý vô thượng, phá hủy hồ lô đen, chém đôi cường giả Hắc Vân tộc rồi hóa thân thành kiếm thần, giết chết Vương giả Hỏa Ngưu tộc đang tháo chạy. Trước uy lực của vòng Ngũ Hành, Thạch Hạo lấy thân thể và quyền ấn đối kháng trực diện, sau đó mở hàng loạt Động Thiên thành thần bàn để giam cầm bảo cụ giữa hư không. Hắn tiếp tục phá cốt thuẫn, chém mất một tay của Tần Thủ Thành, nhưng thần niệm bí ẩn ẩn trong vòng Ngũ Hành bất ngờ thức tỉnh, mang Tần Thủ Thành và Tần Siêu độn thổ trốn đi; kiếm khí truy kích vẫn khiến hai kẻ này chịu thương tổn nặng nề. Thạch Hạo bắt giữ những người Bất Lão sơn bị bỏ lại để tìm tung tích cha mẹ, song không thu được manh mối, còn cấm chế trong biển ý thức đã khiến các tù binh tự hủy nguyên thần khi hắn dò xét bảo thuật. Sau khi chém đầu Vương giả cuối cùng, hắn lạnh lùng chất vấn quần hùng, khiến cả tu sĩ Hoang Vực lẫn sinh linh vực ngoại đều im tiếng vì sợ hãi. Trận chiến này xác lập uy nghiêm phong Vương và tư thế vô địch của Thạch Hạo, khiến những thiên tài đồng thế hệ hiểu rằng hắn đã vượt xa họ và bắt đầu hướng mắt tới các cường giả đời trước cùng những sinh linh cổ đại."},{"chuong":410,"tieuDe":"Tìm Kiếm Phương Pháp Đột Phá","tomTat":"Sau khi đánh bại người Bất Lão sơn, Thạch Hạo khiến các thiên tài vực ngoại không còn dám xem thường Hoang Vực và được công nhận là người dẫn đầu cùng thế hệ. Nó hội ngộ Cửu đầu sư tử, Hỏa Nha, chim loan năm màu cùng những bằng hữu từng đồng hành tại Bách Đoạn sơn, đồng thời biết Cửu đầu sư tử dù được bồi dưỡng bằng nhiều tài nguyên quý giá vẫn chưa thể đuổi kịp mình. Hỏa Nha bí mật cảnh báo rằng Nguyệt Thiền đã bước vào Liệt Trận cảnh từ lâu, từng lấy hoa Ly Hỏa Linh và đang chuẩn bị niết bàn, khiến Thạch Hạo càng thêm dè chừng. Qua cuộc trò chuyện, nó hiểu rằng muốn vượt khỏi Liệt Trận Vương cảnh thì chỉ dựa vào bản thân là vô cùng khó khăn, thường phải dùng linh dược hoặc tiểu niết bàn đan để rèn thân thể và mở thần tàng. Trước áp lực từ Bất Lão sơn, Bổ Thiên giáo cùng những đối thủ như Đại Thạch và Nguyệt Thiền, Thạch Hạo quyết tìm cách nhanh chóng tiến lên cảnh giới cao hơn. Cửu đầu sư tử đưa nó tới luận đạo với tám lão Vương, và một lão Vương Hỏa quốc tiết lộ rằng tổ địa Thạch tộc cất giữ truyền thừa còn mạnh hơn tổ địa Hỏa quốc, có thể giúp nó sớm đột phá Liệt Trận Vương cảnh."},{"chuong":411,"tieuDe":"Truyền Thừa Của Tổ Địa Thạch Tộc","tomTat":"Các lão Vương tiết lộ với Thạch Hạo rằng di sản quý giá nhất của Thạch quốc không phải công pháp mà là những phương thuốc thượng cổ từng khiến Thái Cổ Thần Sơn và các đại giáo Hoang Vực thèm muốn. Chúng không đơn thuần dùng để luyện đan mà có thể phối hợp âm dương, thủy hỏa nhằm rèn luyện cả thân thể lẫn tinh thần, khai mở tiềm năng và giúp người tu hành niết bàn mà không lưu lại tai họa. Tuy nhiên, hoàng tộc Thạch quốc chỉ còn giữ những phương thuốc không hoàn chỉnh, còn tổ địa thì từng được Tế Linh mạnh nhất che giấu bằng một trận pháp kinh thế. Khi biết truyền thừa đầy đủ gồm năm phương thuốc, Thạch Hạo chợt nhận ra Thạch thôn vẫn bảo tồn trọn bộ từ thời thượng cổ, và những lần tắm dược của trẻ nhỏ trong thôn chính là cách truyền thừa cốt lõi ấy được duy trì qua nhiều thế hệ. Nó cũng hiểu rằng hiệu quả trước kia bị hạn chế vì dân làng không đủ sức thu thập linh dược cùng nguyên thủy bảo huyết đúng yêu cầu, buộc phải dùng nhiều vật liệu thay thế. Dù vô cùng kích động trước con đường có thể giúp mình nhanh chóng mạnh lên, Thạch Hạo vẫn kín đáo che giấu phát hiện này để tránh dẫn tới một cuộc tranh đoạt lớn. Cuối cùng, lời nhắc về bảo đỉnh chuyên rèn luyện thân thể của Thạch tộc khiến nó nghi ngờ chiếc đỉnh đen từng phát ra âm thanh thần bí ở Thạch thôn chính là trọng bảo truyền thừa ấy."},{"chuong":412,"tieuDe":"Linh Dược Quan Trọng","tomTat":"Thạch Hạo biết chiếc đỉnh đen mình sử dụng từ nhỏ chính là bảo đỉnh thượng cổ của Thạch tộc, có khả năng gia tăng dược tính và từng thức tỉnh khi luyện chân huyết. Dù được các lão Vương đánh giá đủ tư chất kế thừa Thạch quốc và khuyên bế quan để tránh những thế lực lớn, nó vẫn quyết định nhập thế, tiếp tục tiến lên giữa hiểm nguy để rèn luyện bản thân. Qua cuộc trò chuyện, Thạch Hạo biết Hỏa Diễm sơn có kỳ dược trợ giúp đột phá Tôn giả, còn một vùng đất màu vàng chứa thần tính bất hủ nhưng được quy tắc đáng sợ bảo vệ. Sau đó, sự xuất hiện của Bạch Hổ vương khiến nhóm Đại Hồng Điểu và Cửu đầu sư tử cảnh giác vì mối thù tại Bách Đoạn sơn cũng như việc Thú sơn Tây Lăng từng tham gia hủy diệt Bổ Thiên các. Từ Tử Điêu và Hỏa Nha, Thạch Hạo tìm được manh mối rằng Trúc Hoàng Tuyền, chủ dược không thể thay thế trong phương thuốc nó cần, từng xuất hiện tại Thú sơn Tây Lăng nên dự tính sẽ đến khu cổ lăng nguy hiểm này thăm dò. Trong lúc cả nhóm thu mua bảo dược, các sinh linh thuần huyết từ Thái Cổ Thần Sơn mang linh dược quý tới trao đổi, còn Vân Hi vừa nhận ra Thạch Hạo đã lập tức tiến đến ôm chặt cánh tay nó, khiến những người đồng hành của nàng kinh ngạc và bất mãn."},{"chuong":413,"tieuDe":"Kim Sí Đại Bằng","tomTat":"Vân Hi khẩn thiết yêu cầu Thạch Hạo trả lại pháp khí Thần Linh của bộ tộc mình, tiết lộ rằng khi hai bộ phận hợp nhất, chúng sẽ trở thành chìa khóa mở một môn hộ phủ bụi liên quan đến bí mật thần vực. Tuy nhiên, Thạch Hạo nhớ lời Nhị Ngốc Tử căn dặn nên kiên quyết không trao đổi, đồng thời suy đoán món đồ này gắn với bí mật Thiên Nhân tộc từng khiến Nhị Ngốc Tử phải lẩn trốn. Một thiếu niên Kim Sí Đại Bằng đứng ra ép Thạch Hạo trả bảo vật, nhưng bị Đại Hồng Điểu bác bỏ lý lẽ và bị khí thế cùng lời cảnh cáo của Thạch Hạo buộc phải lùi bước. Mọi người nhận ra tộc Kim Sí Đại Bằng có thể còn nhắm đến bảo thuật Côn Bằng trong tay Thạch Hạo, bởi bộ tộc hùng mạnh này luôn khao khát truyền thừa hoàn chỉnh của Côn Bằng. Thiếu niên tóc vàng tuyên bố Vân Hi sắp trở thành chị dâu mình, vì huynh trưởng của y vừa từ vực ngoại trở về và đã theo bộ tộc tới Thiên Thần sơn cầu hôn. Vị kỳ tài Kim Sí Đại Bằng sau đó xuất hiện bằng thân pháp cực tốc, nhưng Vân Hi lập tức phủ nhận quan hệ, ôm lấy cánh tay Thạch Hạo và nhờ hắn làm lá chắn để cự tuyệt đối phương. Dù nhận ra mình đang bị lợi dụng, Thạch Hạo vẫn thuận thế ôm Vân Hi rồi cắn mạnh vào tai nàng, tái hiện cảnh thân mật năm xưa tại Bách Đoạn sơn và đẩy mâu thuẫn với người cầu hôn lên cao."},{"chuong":414,"tieuDe":"Ngoài Ý Muốn","tomTat":"Vân Hi định mượn uy thế của Thạch Hạo làm bia đỡ đạn, nhưng lại bị hắn cắn tai trước đám đông, khiến nàng vừa tức giận vừa xấu hổ. Khi Kim Vân Thanh tuyên bố nàng sẽ gả vào Thái Cổ Bằng Sơn, Vân Hi lập tức phủ nhận và khẳng định không muốn bàn đến chuyện riêng tư. Kim Vân Thanh dùng khí thế uy hiếp Đại Hồng Điểu, song chỉ một tiếng hừ ẩn chứa đại đạo thần âm của Thạch Hạo đã khiến hắn sắc mặt trắng bệch. Kim Vân Đằng kịp thời ngăn em trai, thừa nhận Thạch Hạo là thiên kiêu và tôn trọng lựa chọn của Vân Hi, sau đó chủ động rời đi; Thạch Hạo cũng nhận ra người này đã đạt Liệt Trận cảnh và là một Vương giả trẻ tuổi cực mạnh. Sau khi từ chối các điều kiện đổi Thần linh pháp khí của Vân Hi, Thạch Hạo tiếp tục giao dịch và thu được hơn mười loại linh dược cần thiết, rồi dự yến tiệc do Hỏa Linh Nhi tổ chức, nơi nàng cố ý dùng món tai lợn để trêu chọc hắn. Cuối cùng, bất chấp lời cảnh báo rằng có thể bị tập kích ngoài Hoàng Đô, Thạch Hạo vẫn lên đường du ngoạn Hoang Vực cùng Cửu Đầu Sư Tử và các bạn, còn Hỏa Linh Nhi ôm sói con cùng Vân Hi cũng bất ngờ nhập đoàn."},{"chuong":415,"tieuDe":"Dược Đô","tomTat":"Rời Hoàng Đô, đoàn Thạch Hạo vẫn luôn đề phòng tập kích, nhưng rồi nhận được tin Huyết Thần Lâu đã từ chối khoản treo thưởng khổng lồ nhằm lấy mạng hắn và hoàn trả toàn bộ phù cốt. Để nhanh chóng vượt qua cửa ải Liệt Trận Vương cảnh bằng đan phương tổ truyền, Thạch Hạo nghe theo lời khuyên của Hỏa Linh Nhi và Cửu Đầu Sư Tử, quyết định tới Dược Đô thu mua linh dược. Cả nhóm dùng Hư Không thú bì vượt đường dài, xuất hiện tại một dãy núi gần đích rồi bay tới cổ thành được bao quanh bởi vô số vườn thuốc, nơi Hoàng Kim Dược Điệp giúp cây cỏ sinh trưởng mạnh mẽ. Khi tiến vào thành, họ bị một Linh Dược cây hơn năm nghìn năm tuổi dò xét ác ý và kinh ngạc trước nguồn gốc biến dị nhờ lôi kiếp dịch của nó. Trong khu chợ phồn thịnh nhưng thật giả lẫn lộn, cả đoàn bắt gặp đủ loại kỳ dược cùng những kẻ rao bán hàng đáng ngờ dưới danh nghĩa Bán Thần cỏ và Hoàng Kim Dược Điệp. Cuối cùng, Thạch Hạo chứng kiến một Dược Đằng Thông Linh dùng hoa hình đỉnh đồng tự luyện thuốc, đồng thời được một bà lão báo rằng Dược Đô có thể sắp xuất hiện thần thánh chí bảo Cổ Dược."},{"chuong":416,"tieuDe":"Hoàng Cốt","tomTat":"Tại Dược đô, Thạch Hạo cùng mọi người chứng kiến Hỏa Kim Đằng hấp thu kim loại, kết hoa thành đỉnh và dùng Thần Hỏa luyện ra dược đan có linh tính phi phàm. Khi vận dụng Trùng Đồng, nó phát hiện bên trong linh đằng có một người tí hon bằng lửa bị xích thần trật tự trói buộc, từ đó nghi ngờ cây đã bị đoạt xác và có thể liên quan đến tai họa sắp giáng xuống Hoang Vực. Đến khu phố dược liệu, Thạch Hạo lần lượt nhìn thấu khối thánh cốt đã gần cạn thần tính được rao là Chân Long cốt và chiếc mai rùa trắng chắp vá dùng để lừa khách. Trong một đống xương cốt cùng khoáng thạch tơi tả, nó tìm thấy khối cốt đen ẩn chứa thần quang rực rỡ rồi mua trọn số hàng bằng một bảo cụ Minh Văn cảnh. Sau khi nghe tin trong sơn cốc vừa xuất hiện những mảnh xương nghi là Chân Hoàng cốt, chủ sạp A Đức cùng người đàn ông trung niên lập tức đòi hủy giao dịch, thậm chí ra tay cướp lại nhưng bị Thạch Hạo nhẹ nhàng ngăn cản. Giữa lúc một đại nhân vật ngồi trên xe tám hung thú dừng lại và nghe lời vu cáo rằng Thạch Hạo ép mua bảo cốt, tin Thần cốc có thể là nơi Chân Hoàng vẫn lạc, đồng thời đã xuất hiện thần vật bất hủ, bất ngờ truyền khắp Dược đô và gây nên náo động lớn."},{"chuong":417,"tieuDe":"Thần Cốc Kỳ Dược","tomTat":"Tin Thần cốc có thể là nơi Chân Hoàng vẫn lạc và ẩn chứa Chân Hoàng cốt khiến Dược đô chấn động, vô số cường giả lập tức lên đường tranh đoạt cơ duyên. Trước khi rời đi, Thạch Hạo dùng một khối xương bình thường đánh tráo bảo cốt thật, qua mặt người trung niên dũng mãnh và tránh giao chiến để không làm bại lộ thân phận. Theo dòng tu sĩ tiến sâu vào thần mạch, đoàn người phát hiện Thần cốc được bảo vệ bởi gần trăm trận pháp liên kết, có khả năng cấm không và vặn vẹo hư không, đến Tôn giả cũng khó cưỡng ép phá vỡ. Tại đạo đài quan sát, các đại nhân vật kiểm tra khối cốt do một người trẻ tuổi giao ra và xác định đó chỉ là di cốt chim thần cấp Thiên gần cạn thần tính, chưa đủ chứng minh nơi đây có Chân Hoàng cốt. Vận dụng Trùng Đồng nhìn xuyên qua những lớp cấm chế, Thạch Hạo phát hiện trong trung tâm sơn cốc có một cây kỳ dược nhỏ mang ba đóa hoa. Đóa thứ nhất hóa thành người tí hon, đóa thứ hai ngưng tụ thành pháp khí biến ảo giữa tháp, lò và đỉnh, còn đóa thứ ba vẫn bất động, báo hiệu bí mật của Thần cốc vẫn chưa thực sự hiển lộ."},{"chuong":418,"tieuDe":"Linh Căn Đệ Nhất Thiên Hạ","tomTat":"Dùng Trùng Đồng quan sát cây nhỏ bị hơn trăm tòa trận pháp bảo vệ trong Thần cốc, Thạch Hạo chứng kiến ba đóa hoa thông linh, lần lượt hóa thành người tí hon tu hành và pháp khí có khả năng trợ ngộ đạo, rèn luyện thân thể. Qua lời kể của hắn, Vân Hi nhận ra dị tượng ấy ẩn chứa áo nghĩa thiên địa và khẳng định ngay cả thánh dược của Thiên Thần sơn cũng không thể sánh bằng, khiến cả nhóm suy đoán đây ít nhất là linh căn đứng đầu Hoang Vực, thậm chí đến từ ngoài giới này. Hỏa Linh Nhi liên hệ nó với truyền thuyết về sự vẫn lạc của Dược thần thượng cổ, còn mọi người lo ngại khi trận pháp mở ra giữa đại loạn Hoang Vực, nơi đây sẽ biến thành chiến trường tranh đoạt đẫm máu của các thế lực lớn. Không đủ sức phá trận, cả nhóm trở về Dược đô, nơi Thạch Hạo huy động các bạn đồng hành phân tán thu mua nguyên liệu cho Niết Bàn đan và gom được bốn mươi tám cây bảo dược, làm thị trường chấn động. Vì vẫn thiếu nhiều chủ dược quý hiếm, hắn từ bỏ ý định luyện đan hoàn chỉnh, chuyển sang dùng số dược liệu hiện có để khai mở một phần tiềm năng thân thể và tìm cơ hội đột phá. Hỏa Linh Nhi tìm được một đình viện hẻo lánh có dược đỉnh đã tích lũy linh tính suốt hơn nghìn năm; Thạch Hạo thuê nơi này trong ba ngày rồi nhờ mọi người hộ pháp, chuẩn bị bắt đầu lần rèn luyện thân thể quan trọng."},{"chuong":419,"tieuDe":"Thân Thể Kim Đan","tomTat":"Tại Dược đô, Hỏa Nha nhận ra ngọn lửa bạc dưới dược đỉnh là Địa mạch linh diễm, còn Thạch Hạo quyết định tận dụng chiếc đỉnh ngàn năm để luyện chính thân thể mình. Sau khi điều chỉnh trạng thái và để linh thân khống chế hỏa lực, hắn nhập đỉnh, lần lượt cho vào gần hai mươi loại linh dược, độc trùng, xương thú, gân giao và khoáng thạch, đồng thời dùng nhiều vật thay thế vì chưa thu thập đủ nguyên liệu luyện Tiểu Niết Bàn đan. Hắn vận dụng phương thuốc phụ trợ đã thất truyền của hoàng tộc Thạch quốc, phối hợp đạo hỏa trong cơ thể, địa hỏa bên ngoài và bí pháp kết ấn nhằm khuếch đại dược tính, khai mở tiềm năng. Tinh khí tám phương, cuồng phong và lôi điện ùn ùn hội tụ khiến Hỏa Linh Nhi phải cùng mọi người dựng trận kỳ che giấu dị tượng khỏi Dược đô. Khi nước trong đỉnh cạn hết, linh khí và dược lực cô đặc thành dược nê bao bọc Thạch Hạo, cuối cùng hóa thành một viên Kim đan vàng nhạt hấp thu cả lôi điện lẫn linh diễm. Kim đan liên tục nứt vỡ rồi khép lại, thân thể Thạch Hạo cũng rạn nứt và chảy máu dưới sức ép lột xác, nhưng nhờ đó hắn phá tan bình cảnh và tiến vào Liệt Trận cảnh trung kỳ. Sau khi đột phá, hắn tiếp tục luyện thân trong đỉnh và bắt đầu khắc họa trận pháp bên trong cơ thể để củng cố sức mạnh của cảnh giới Liệt Trận."},{"chuong":420,"tieuDe":"Lột Xác Thành Công","tomTat":"Thạch Hạo hội tụ tinh hoa thủy hỏa và dược lực Kim đan vào dược đỉnh, khắc thành những trận pháp Côn Bằng, Chu Tước, Chu Yếm cùng cây cỏ trong máu thịt, qua đó chữa lành thân thể và ổn định Liệt Trận cảnh trung kỳ. Sau khi hấp thu tám phần dược lực và hoàn tất lột xác, cậu luyện phần còn lại thành hai viên Kim đan mới. Hậu nhân của thái thượng trưởng lão Thần Dược môn lấy cớ thu thuế linh diễm để cưỡng đoạt đan dược, nhưng bị Thạch Hạo đánh ngất rồi phế sạch tu vi. Thái thượng trưởng lão vừa trừng phạt A Đức và người trung niên đã gây chuyện, vừa định ép Thạch Hạo giao đan, song bàn tay pháp lực của ông bị cậu dùng một quyền đánh tan. Nhận ra thiếu niên trước mặt chính là tiểu Thạch, vị trưởng lão lập tức cúi đầu nhận sai và đưa hậu nhân rời đi. Sau đó, ông trở về giếng tổ của Thần Dược môn, viện dẫn giao ước để cầu cô gái áo xám từng mang thi thể Thạch Nghị khỏi hồ Ma Linh ra tay đối phó Thạch Hạo."},{"chuong":421,"tieuDe":"Lai Lịch Của Cô Gái Áo Xám","tomTat":"Bên Giếng tổ của Thần Dược môn, cô gái áo xám buộc Lâm Côn đi mời Thạch Hạo và ban cho lão chữ “Ngự” hộ thân. Sau khi thu hai viên Kim đan mới luyện, nhận ra tài nguyên tích trữ gần như cạn kiệt và không đạt được thỏa thuận trao đổi pháp khí Thần Linh với Vân Hi, Thạch Hạo đối đầu Lâm Côn nhưng mọi đòn sấm chớp đều bị chữ vàng hóa giải. Khi nó dùng kiếm gãy, cô gái áo xám từ xa giam cầm kiếm quang rồi hiện thân, dẫn riêng nó lên ngọn núi thấp tới Giếng tổ. Nàng tiết lộ từng gặp chủ nhân đời trước của thanh kiếm, nhận xét nó đã mất đạo vận, đồng thời cảnh báo Hoang Vực sắp đại loạn và Dược đô sẽ trở thành nơi chinh phạt. Trước nghi vấn về trận chiến giữa Chí Tôn cốt và Trùng Đồng, nàng khẳng định cuộc giao tranh tại Hư Thần giới mới chỉ là thăm dò vì áo nghĩa tối cao của Trùng Đồng chưa được thi triển. Cuối cùng, đôi mắt nàng phân tách thành Trùng Đồng chứa khí hỗn độn, khiến Thạch Hạo kinh hãi nhận ra mình đang đứng trước một Trùng Đồng giả từ thời thượng cổ."},{"chuong":422,"tieuDe":"Trùng Đồng Giả Thời Thượng Cổ","tomTat":"Trên ngọn núi có giếng cổ, cô gái áo xám phân tách Trùng Đồng, tạo nên dị tượng hủy diệt và khí hỗn độn, đồng thời xác nhận nàng đã sống từ thời thượng cổ. Sức mạnh của đôi mắt khiến Thạch Hạo thất thần, để lộ nhiều suy nghĩ riêng tư, nhưng ảnh hưởng ấy biến mất khi Trùng Đồng hợp nhất trở lại. Cô gái không giao chiến vì cảnh giới hai bên quá chênh lệch, chỉ mong sau này Thạch Hạo sẽ chân chính quyết đấu với một Trùng Đồng giả khác; trước lúc rời đi, nó còn vì tò mò chuyện quá khứ của nàng mà bị phất tay đánh xuống chân núi. Tại Bất Lão sơn ở Huyền Vực, các nhân vật cấp cao quyết định tìm kiếm và nhã nhặn đón về một đứa trẻ mang nửa huyết thống của họ, bất chấp nguy cơ đứa trẻ bị cuốn vào kế hoạch niết bàn. Một pháp chỉ được đóng thần ấn tổ truyền rồi phá không xuyên qua vực bích đã phong ấn, trong khi một thiếu niên của Bất Lão sơn tuyên bố tương lai sẽ nắm giữ chí bảo, hiệu lệnh thiên hạ và trở thành Chí Tôn đệ nhất. Trở lại Dược đô, dù được Hỏa Nha cảnh báo về sự đáng sợ của Bất Lão sơn và Bổ Thiên giáo, Thạch Hạo vẫn khẳng định không cần lão tổ hay truyền thừa che chở, quyết tự mình tranh lấy tất cả trên con đường riêng."},{"chuong":423,"tieuDe":"Kỳ Dược","tomTat":"Dưới chân núi, Thạch Hạo chặn đường Lâm Côn bằng tốc độ Côn Bằng, dùng quyền lực và lôi điện Toan Nghê áp đảo, buộc vị thái thượng trưởng lão Thần Dược môn phải nhận thua và chuộc mạng. Lâm Côn dẫn cả nhóm tới vườn thuốc được trận pháp bảo vệ, giao ra bốn kỳ dược quý hiếm gồm Hoàng Kim thảo, Lạc Nguyệt hoa, Tử Tinh lan và Lưu kim tuế nguyệt. Thạch Hạo ngoài mặt tỏ vẻ chưa hài lòng nhưng thực chất vô cùng vui mừng, bởi đây đều là những chủ dược cần thiết để luyện tiểu Niết Bàn đan, giúp nó chuẩn bị tiến lên cảnh giới Tôn giả. Khi bị ép phải đưa ra thêm vật bồi thường, Lâm Côn tiết lộ Dược thần thời thượng cổ từng tìm được một ấu trùng Hoàng điệp và phong ấn nó trong bình Thần Băng. Sinh linh này không chỉ có khả năng tìm kiếm linh dược mà còn đứng trên Hoàng kim dược điệp, khiến các dược điệp khác tự nguyện trở thành phó điệp bảo vệ nó. Nghe truyền thuyết Hoàng điệp từng sở hữu chiến lực cái thế, ánh mắt Thạch Hạo lập tức trở nên nóng rực trước manh mối về thần trùng chưa từng xuất thế ấy."},{"chuong":424,"tieuDe":"Bên Trên Hoàng Kim","tomTat":"E ngại thực lực và tiềm năng của Thạch Hạo, Lâm Côn quyết định kết thiện duyên, trao cho hắn nửa miếng đồng thau khắc đầy ký hiệu thần bí cùng manh mối dẫn tới Hoàng điệp. Qua ghi chép của Thần Dược môn và lời Vân Hi, mọi người biết Hoàng điệp là thần trùng cực kỳ hiếm, được xưng tụng là sinh linh bên trên Hoàng kim, thậm chí có tiềm năng sánh với Thập Hung Thái Cổ. Nửa miếng đồng thau còn lại từng thuộc về con của Dược thần, người đã bỏ mạng khi thăm dò Thần cốc thượng cổ, vì vậy Lâm Côn dẫn cả đoàn vượt qua sự phong tỏa của các cường giả Dược đô để tiến vào đường hầm cổ. Sau khi đi qua hai tầng trận pháp rộng lớn như những thế giới riêng, họ nhận ra toàn bộ hệ thống hơn trăm tầng đang hút tinh khí và linh mạch trong phạm vi mênh mông về trung tâm để nuôi dưỡng một linh căn thiên địa. Tại tầng thứ ba, cả nhóm tìm thấy hài cốt xám đen của con Dược thần; thần quang còn sót lại trong xương cho thấy người này có thể đã đạt cấp Thần nhưng vẫn bị trận văn nghiền chết và hút cạn tinh hoa. Khi Thạch Hạo gần như từ bỏ việc tìm kiếm, Trùng Đồng bất ngờ cảm ứng được khí thế tương đồng với vật hắn đang giữ, giúp hắn xác nhận nửa miếng đồng thau còn lại quả thực nằm giữa cấm chế nguy hiểm của tầng trận pháp thứ ba."},{"chuong":425,"tieuDe":"Thế Giới Hộp Báu","tomTat":"Nhờ Trùng Đồng giả nhìn xuyên sương mù, Thạch Hạo phát hiện nửa miếng đồng nằm sâu trong trận pháp có thể ghép với mảnh mình đang giữ. Chim loan năm màu thử thăm dò nhưng bị tầng trận pháp Thiên Thần phản kích đến thổ huyết, chứng minh nơi đó đủ sức tiêu diệt cả cường giả cấp Thần. Hỏa Linh Nhi và Vân Hi nhận ra hai mảnh đồng vốn thuộc về Thế giới hộp báu, một bảo vật thời thái cổ có thể dựng nên tiểu thế giới để cất giấu Thần tàng. Khi Thạch Hạo truyền thần lực vào mảnh đồng, hơn trăm ký hiệu đồng loạt cộng hưởng, kéo nửa còn lại vượt qua sát quang rồi hợp nhất thành một vật bằng đồng hoàn chỉnh. Cả nhóm rời sơn cốc và lần lượt tìm cách mở hộp báu nhưng đều thất bại, trong khi Đại Hồng Điểu nghi ngờ Hoàng điệp cùng những bảo vật khác đang được cất bên trong. Thạch Hạo bèn nhờ Tiểu Tháp phá các trận pháp và đoạt bảo dược, song được cảnh báo rằng linh căn trong sơn cốc do một tồn tại đáng sợ tạm trồng, động vào có thể khiến kẻ đó giáng lâm. Nhớ lại lời cảnh báo của cô gái áo xám, Thạch Hạo từ bỏ ý định cưỡng đoạt linh căn và yêu cầu Tiểu Tháp ưu tiên mở Thế giới hộp báu."},{"chuong":426,"tieuDe":"Mở Ra","tomTat":"Tiểu Tháp tiết lộ Hoàng điệp có tiềm lực sánh ngang Thập Hung, khiến Thạch Hạo càng quyết tâm tìm ra sinh linh thần bí này. Hắn đưa mọi người rời Thần cốc đến một dãy núi vắng gần Dược đô, rồi nhờ Tiểu Tháp dùng khí hỗn độn sắp xếp lại hơn trăm ký hiệu trên hộp báu đồng thau, mở ra cánh cửa dẫn vào tiểu thế giới. Bên trong chỉ có một bàn đá và tấm da thú do Dược thần để lại, ghi rằng trứng Hoàng điệp đã được chuyển tới địa mạch tổ căn dưới Dược đô để hấp thu tinh hoa thiên địa, sau đó sẽ tự động trở về bình Thần Băng và tiếp tục bị phong ấn. Lâm Côn dù kinh động trước giá trị của bí mật này vẫn chấp nhận việc đã trao hộp báu cho Thạch Hạo, xem đó là sự đầu tư vào tương lai của hắn. Dựa theo di thư, cả nhóm trở lại Dược đô, mất hai ngày tìm thấy tế đàn ngầm và kích hoạt trận pháp truyền tống mà không cần xông vào trọng địa của Dược Thần môn. Khi linh khí quanh ngọn núi thấp bỗng sôi trào, bình Thần Băng trắng như tuyết biến mất khỏi ao linh dịch trong địa mạch tổ căn và được truyền tống ra bên ngoài, nhưng trạng thái của trứng Hoàng điệp bên trong vẫn chưa được xác định."},{"chuong":427,"tieuDe":"Xuất Thế","tomTat":"Tại khu vườn hoang của Dược Thần, nhóm Thạch Hạo đào được một tế đàn cổ và triệu hồi thành công bình Thần Băng chứa sinh linh đã bị phong ấn từ thời thượng cổ. Bảo vật xuất thế khiến linh khí quanh núi thấp ở trung tâm Dược đô dâng trào, làm toàn bộ Thần Dược môn kinh động và đổ xô tới kiểm tra. Dù Thạch Hạo đã giấu chiếc bình vào Thế giới hộp báu rồi đặt trong Tiểu tháp, cô gái áo xám vẫn phát hiện mọi chuyện bằng Tha tâm thông, nhưng nàng không tranh đoạt mà chỉ yêu cầu được mượn Hoàng điệp ba ngày sau khi nó nở, và hắn đã đồng ý. Sau đó, cả nhóm tiến vào tiểu thế giới, chịu đựng hàn khí đáng sợ của bình Thần Băng và dựa theo tấm da thú để mở phong ấn. Vật bên trong ban đầu trông như một viên Kim đan tỏa dược hương, nhưng dưới sự thăm dò của Thạch Hạo đã hiện nguyên hình thành một thần trùng màu vàng giống con tằm. Thần trùng lập tức lao lên người Thạch Hạo rồi liên tục đòi hỏi một vật có thể nuôi dưỡng nó, khiến hắn vừa kinh ngạc vừa vui mừng."},{"chuong":428,"tieuDe":"Thức Ăn Của Thần Trùng","tomTat":"Hoàng điệp vừa xuất thế đã quấn quýt bên Thạch Hạo, nhưng dược hương và sắc vàng nhanh chóng phai nhạt, khiến Vân Hi cảnh báo rằng nó phải hấp thu những vật thần thánh mới có thể sống sót. Thạch Hạo mở túi Càn Khôn cho nó tự chọn thức ăn; nó chỉ lưu dấu trên Bất Lão Tuyền và Thái Nhất Chân Thủy, rồi uống rượu thái cổ và gặm côn mộc để khôi phục sức sống. Sau đó, thần trùng tìm thấy cành liễu bảo mệnh do Liễu Thần ban tặng, ăn ba chồi non để củng cố tinh hoa trời sinh rồi ôm chặt cành cây chìm vào giấc ngủ. Ba ngày sau, nó tỉnh dậy và tàn phá bốn cây kỳ dược của Thạch Hạo, khiến Hoàng kim thảo, Lạc nguyệt hoa, Tử tinh lan và Lưu kim tuế nguyệt đều tổn hại nặng, may vẫn còn rễ để trồng lại. Nhờ hấp thu lượng lớn tinh hoa, Hoàng điệp nhanh chóng lột xác, dễ dàng xuyên thủng pháp khí thông thường và thu liễm hoàn toàn khí tức khi hóa thành một hạt châu vàng trên tóc Thạch Hạo. Nhận ra thần trùng có thể bí mật đột nhập nơi cất giữ linh dược, Thạch Hạo lập tức nảy ý định càn quét Thái Cổ Thần Sơn và hỏi Vân Hi về những ngọn núi sở hữu nhiều kỳ dược."},{"chuong":429,"tieuDe":"Pháp Chỉ Của Bất Lão Sơn","tomTat":"Một tờ pháp chỉ của Bất Lão sơn xuyên qua vực bích, giáng xuống hoàng đô Hỏa quốc và truyền lệnh triệu kiến Thạch Hạo, khiến cả Hoang Vực chấn động. Đang ở Dược đô lo tìm linh dược nuôi ấu trùng Hoàng điệp, Thạch Hạo biết tin liền sắp xếp đưa Đại Hồng Điểu tới tổ địa Hỏa quốc bái Tế Linh làm sư, nhưng nó vừa đến đã bị trừng trị vì chuyện sơn bảo. Nhận thấy phong ba sắp nổi, Thạch Hạo cũng khuyên Cửu đầu sư tử và Hỏa Nha trở về, không muốn các đồng bạn bị cuốn vào nguy hiểm. Khi người giữ pháp chỉ liên tục thúc ép và đe dọa, Thạch Hạo công khai đáp trả rằng người của Bất Lão sơn phải tới Dược đô yết kiến mình, khiến đối phương nổi giận và nảy sinh sát ý. Uy danh của tiểu Thạch khiến nhiều đại nhân vật tại Dược đô kéo tới bái phỏng, dâng linh dược hóa giải hiềm khích, vô tình giúp nó tạm giải quyết thức ăn cho Hoàng điệp. Sau đó, biết một bức thư từ vực ngoại đã được chuyển tới Hoang Thiên hầu phủ, Thạch Hạo quyết định trở về hoàng đô Thạch quốc vì cha mẹ và ông nội đều đang ở bên ngoài Hoang Vực. Nó còn bàn với Tiểu Tháp chuẩn bị nuốt pháp chỉ nếu Bất Lão sơn dùng uy thế áp bức, sẵn sàng giao chiến nếu đối phương không chân thành dù giữa hai bên có thể tồn tại quan hệ máu mủ."},{"chuong":430,"tieuDe":"Thiên Thần Sơn Bí Mật","tomTat":"Trước khi rời Dược Đô, Thạch Hạo nhận từ Môn chủ Đan Đỉnh Giáo một đóa hoa quý của cây Linh Dược từng hấp thu Lôi Kiếp dịch và sắp tiến hóa thành Thánh Dược. Biết cổ giáo này đã suy tàn, hắn nhận lời để ý tới người con trai của Môn chủ, kẻ đã lưu lạc nhiều năm nhằm tìm lại truyền thừa luyện đan thất lạc. Thạch Hạo sau đó lên đường tới Thạch quốc Hoàng Đô, vừa để xem bức thư đang chờ mình, vừa tìm thêm Linh Dược luyện Tiểu Niết Bàn đan, chuẩn bị cho con đường tiến lên Tôn Giả. Trên Hư Không da thú, hắn cùng Hỏa Linh Nhi, Cửu Đầu Sư Tử và Hỏa Nha gây sức ép, buộc Vân Hi phải giải thích bí mật của đôi bao cổ tay mà Thiên Nhân Tộc quyết giành lại. Vân Hi tiết lộ chúng là chìa khóa mở một Thái Cổ trận pháp có thể đưa người ta rời khỏi đại vực lao tù, dù điểm đến hoàn toàn chưa rõ. Bí mật này bắt nguồn từ cốt thư của Thái Cổ Thiên Nhân và đủ sức khiến Bổ Thiên Giáo, Bất Lão Sơn cùng Tây Phương Giáo đánh chiếm Thiên Thần Sơn, đồng thời xác nhận việc Nhị Ngốc Tử năm xưa bị truy sát có liên quan đến nó. Khi bị hỏi vì sao Thiên Nhân Tộc lại vội vã rời Hoang vực, Vân Hi chỉ kịp nói rằng sự thật quá mức đáng sợ, để lại câu trả lời còn dang dở."},{"chuong":431,"tieuDe":"Sự Thật Đầy Đáng Sợ","tomTat":"Vân Hi tiết lộ đại kiếp từng nhiều lần xảy ra từ Thái cổ đến Thượng cổ, sẽ lan khắp các vực và khiến phần lớn Tôn giả cùng cường giả cấp cao biến mất, trong khi mọi chân tướng sau đó đều bị xóa sạch. Cốt thư Thiên Thần Sơn chỉ lưu lại lời đồn ví thế giới như một vườn thuốc, nơi những cường giả đã trưởng thành bị thu hoạch, còn sinh linh yếu hơn được giữ lại, đồng thời ám chỉ một số đạo thống trường tồn có thể liên quan đến nguồn sức mạnh đứng sau tai họa. Những lời ấy khiến Thạch Hạo liên tưởng tới Liễu Thần, cô gái gấp thuyền giấy đen, con đường bí ẩn trong tổ địa Hỏa tộc, gốc dược ngoài thế giới và cô gái áo xám sống từ thời Thượng cổ. Vân Hi đề nghị Thạch Hạo trả lại hộ tí và đưa tộc nhân theo Thiên Nhân tộc rời đại vực bằng trận pháp thái cổ đang được bí mật chuẩn bị, đồng thời cho rằng Bất Lão Sơn có thể là một trong số ít đạo thống không bị đại kiếp ảnh hưởng. Thạch Hạo không lập tức nhận lời vì còn lo cho Thạch Thôn, cha mẹ và tổ phụ, nên quyết định hoãn chuyến đi tới hoàng đô Thạch quốc, dẫn mọi người về thôn để hỏi ý kiến Liễu Thần. Trên đường trở về, nó đùa rằng mình đã mang hai cô gái cùng đám tùy tùng về theo lời dặn của trưởng bối, khiến mọi người phản ứng gay gắt nhưng bầu không khí nặng nề cũng dịu đi."},{"chuong":432,"tieuDe":"Vác Vợ Về Thôn","tomTat":"Thạch Hạo dẫn Hỏa Linh Nhi, Vân Hi cùng các đồng bạn bí mật vượt Đại Hoang trở về Thạch thôn sau khi dùng Trùng Đồng xác nhận không có ai theo dõi. Trên đường xuyên qua hư không bằng tấm da Hư Không thú, cả đoàn bất ngờ gặp những vết nứt đáng sợ do tiến gần tràng vực của một cường giả vô thượng. Thạch Hạo lấy đoạn liễu xanh ra gọi Liễu Thần, khiến không gian lập tức ổn định và giúp mọi người thoát nạn. Khi tới Thạch thôn, tất cả đều chấn động trước vùng đất thanh bình, linh khí dồi dào và Liễu Thần đã khôi phục tới một trăm lẻ tám cành. Nhân lúc Hỏa Linh Nhi và Vân Hi còn ngẩn ngơ, Thạch Hạo vác cả hai vào thôn, khiến dân làng hiểu lầm hắn đã mang hai người vợ trở về. Mọi người nhiệt tình vây quanh trêu chọc hai thiếu nữ, còn lão tộc trưởng Thạch Vân Phong vui mừng đến mức đề nghị tổ chức hôn lễ ngay trong ngày."},{"chuong":433,"tieuDe":"Kinh Động Tới Liễu Thần","tomTat":"Thạch Hạo vác Vân Hi và Hỏa Linh Nhi về Thạch thôn, khiến dân làng hiểu lầm rằng nó muốn cưới cả hai và náo nhiệt chuẩn bị hôn lễ, còn nó phải lấy cớ chờ thêm một năm mới tạm dẹp được chuyện này. Khi tham quan ngôi làng, nhóm khách kinh ngạc trước dược điền đầy linh dược, cây đào bạc chuẩn Thánh dược và những hậu duệ dị thú, trong khi Thạch Hạo tiếp tục trồng thêm các linh dược được bùn cát Bất Lão Tuyền phục hồi. Nghe Thạch Hạo và Vân Hi kể về những bí ẩn bên ngoài, Liễu Thần cảnh báo rằng cảnh giới của nó chưa đủ để truy tìm sự thật, bởi người biết và tiết lộ bí mật có thể bị xóa bỏ, thậm chí khiến Liễu Thần bị cuốn vào đại kiếp nếu ra tay cứu giúp. Liễu Thần từ chối rời khỏi tám vực, bí mật tiết lộ mình đến đây vì chính vùng đất này, đồng thời nhận ra Hoàng điệp trên tóc Thạch Hạo là sinh linh độc nhất không thuộc thế giới hiện tại. Sau khi Nhị Ngốc Tử hé lộ rằng Thiên Thần sơn chưa thực sự hiểu hết trận pháp Thái cổ dùng để thoát khỏi tám vực, Liễu Thần sinh nghi về cửa Sinh bất thường và quyết định âm thầm theo Thạch Hạo cùng Nhị Ngốc Tử tới đó điều tra. Cuối cùng, một bóng người cao ráo, phong hoa tuyệt đại bước ra từ cây liễu mà chỉ Thạch Hạo nhìn thấy; dù hình bóng nhanh chóng biến mất, nó vẫn cảm nhận được Liễu Thần đang ở ngay bên cạnh mình."},{"chuong":434,"tieuDe":"Pháp Tướng Kinh Thế","tomTat":"Trong tiệc đêm tại Thạch thôn, Thạch Hạo liên tục thất thần vì hồi tưởng Pháp tướng Liễu Thần, vô tình ăn quả Hỏa Linh Nhi đã cắn và khiến Vân Hi hiểu lầm những lời hắn lẩm bẩm. Hắn chỉ nhớ quanh Liễu Thần có vô số thần hỏa cùng những điểm sáng tựa ba ngàn thế giới, còn dung mạo siêu phàm ấy lại tự mờ khỏi tâm trí; Tiểu Tháp cũng cảnh báo bí mật này đủ sức làm Thượng giới dậy sóng. Sau khi chiêu đãi mọi người bằng canh thịt Viêm Mãng thuần huyết, sáng hôm sau Thạch Hạo cùng đoàn người dùng da Hư Không thú vượt hàng triệu dặm tới tịnh thổ của Thiên Nhân tộc để chuẩn bị ứng phó đại kiếp. Vân Hi mở trận pháp che giấu, đưa họ vào Thần sơn trọng yếu, nơi Tứ gia hiểu lầm rằng nàng đã bắt Thạch Hạo về để thu hồi pháp khí tổ truyền. Biết con chim trụi lông đi cùng chính là Khổng Tước từng gây họa năm xưa, Tứ gia lập tức trở mặt, nhưng Nhị Ngốc Tử dùng bí mật của một tòa pháp trận để ngăn người Thiên Thần sơn trấn áp mình. Nó còn tố cha và tổ phụ Tứ gia từng chia cắt mình với cô cô của y rồi truy sát mình, tuyên bố trở lại để đòi món nợ nhân duyên. Cuối cùng, Nhị Ngốc Tử chỉ vào Vân Hi và Thạch Hạo, ngang nhiên quyết định bắt nàng về làm vợ cho huynh đệ của mình."},{"chuong":435,"tieuDe":"Thiên Nhân Tộc","tomTat":"Trở lại Thiên Thần sơn, Nhị Ngốc Tử công khai tên thật Khổng Cầu Kỷ và thân phận Khổng Tước Tôn giả, rồi đối chất với Vân Thương Hải về những ân oán cũ cùng mối tình bị chia lìa với Vân Mộng Lan. Dù tu vi và hình dáng đều sa sút, nó vẫn khiến các Tôn giả phải dè chừng nhờ nắm giữ trận đồ và phương pháp tu bổ pháp trận khuyết tổn mà Thiên Thần sơn đang cần. Trong lúc Khổng Cầu Kỷ thương lượng với các trưởng bối, Vân Hi dẫn Thạch Hạo, Hỏa Linh Nhi và những người đồng hành tiến vào tiểu thế giới bí mật cất giữ Thánh dược. Tại hồ nước do linh khí hóa lỏng, họ phát hiện Dẫn Hồn Liên tám lá tám cánh, một Thánh dược có thể cứu người khỏi cái chết và gia tăng mạnh dược hiệu luyện đan, vốn từng hoàn chỉnh với chín lá chín cánh trước khi chân linh bị chém. Hoàng điệp trên đầu Thạch Hạo có dấu hiệu thức tỉnh khi đến gần bảo dược, nhưng bị hắn kịp thời áp chế vì nơi này được trận pháp cấp Thiên Thần bảo vệ. Khi cả nhóm trở lại khu nhà tranh, Khổng Cầu Kỷ bất ngờ tuyên bố Thiên Thần sơn sẽ dùng hôn sự giữa Vân Hi và Thạch Hạo để trả món nợ năm xưa, khiến Vân Hi kinh hãi trước biến cố vừa phát sinh."},{"chuong":436,"tieuDe":"Con Đường Sống","tomTat":"Nhị Ngốc Tử lấy mối tình bị Thiên Thần Sơn ngăn cản năm xưa làm cớ, yêu cầu gả Vân Hi cho Thạch Hạo thì mới chịu giúp tu bổ cổ trận, nhưng Vân Thương Hải kiên quyết để cháu gái tự nguyện quyết định. Vân Kim Hải và Nhị gia lại muốn dùng vũ lực ép nhóm khách giao trả hộ tí tổ truyền và sửa trận, song Vân Kim Hải vừa ra tay đã bị Nhị Ngốc Tử hóa hình đánh trọng thương nhờ Liễu Thần âm thầm trợ lực. Được Vân Hi cảnh báo rằng có cao thủ Thần Đạo hiện diện, Vân Thương Hải lập tức ngăn phe chủ chiến và đưa mọi người đến bãi đá sau núi kiểm tra con đường vượt giới. Nhị Ngốc Tử xác nhận trận đồ mình giữ có thể bổ khuyết cổ trận, nhưng việc khôi phục cần hơn chục loại thần liệu quý hiếm mà bảo khố Thiên Thần Sơn không thể cung cấp đủ, buộc Vân Thương Hải phải tính chuyện hợp tác với một Thần sơn khác. Dù con đường sống trước đại kiếp đã xuất hiện, điều kiện hôn sự vẫn chưa được tháo gỡ, còn Vân Hi được trao toàn quyền lựa chọn và chỉ mỉm cười khi Hỏa Linh Nhi ngỏ ý giúp nàng xử lý Nhị Ngốc Tử. Trong lúc ấy, Thạch Hạo nhìn thấy Liễu Thần nhận ra bóng người được vô số thế giới tế bái chính là kẻ để lại cánh cửa và suy đoán người này vẫn sống ở Hạ giới. Liễu Thần sau đó cảnh báo đại kiếp lần này do nhiều nhân vật đứng sau thúc đẩy, đặc biệt đến mức ngay cả nàng cũng có khả năng bỏ mạng."},{"chuong":437,"tieuDe":"Bằng Tộc Giá Lâm","tomTat":"Thiên Nhân tộc tìm thấy trận pháp vượt giới ẩn trong bãi kỳ thạch và chuẩn bị liên kết các Thần Sơn để thu thập nguyên liệu tu bổ, trong khi Cửu Đầu Sư Tử cùng Chim Loan năm màu quyết định không tranh giành số lượt truyền tống hữu hạn. Liễu Thần chọn ở lại quan sát sóng gió, còn Thạch Hạo cũng chưa muốn rời Hoang Vực vì vẫn chưa tìm được cha mẹ và gia gia Đại Ma Thần. Khi nhóm Thạch Hạo nghỉ trong thần điện trên đỉnh Thiên Thần sơn, Kim Vân Tiêu dẫn cường giả Kim Sí Đại Bằng tộc tới chất vấn và gây sự, nhưng bị Thạch Hạo dùng quy củ của chủ nhà phản bác. Vân Kim Hải xuất hiện, công khai chống lưng cho Bằng tộc và tuyên bố có quyền bác bỏ sự an bài của tộc trưởng Vân Thương Hải, khiến mâu thuẫn nội bộ Thiên Thần sơn lộ rõ. Sau khi bị Thạch Hạo cáo buộc có ý đoạt quyền, Vân Kim Hải tung thần thông tấn công nhưng toàn bộ lông vũ vàng và phù văn đều bị Nhị Ngốc Tử phất tay áo hóa giải. Không chịu dừng lại, Vân Kim Hải yêu cầu lão giả Bằng tộc bắt Nhị Ngốc Tử để tra xét biển ý thức, cưỡng đoạt trận đồ không trọn vẹn, đồng thời ép Thạch Hạo giao ra hộ tí. Trước những lời đe dọa, Thạch Hạo và Nhị Ngốc Tử vẫn không lùi bước, công khai thách thức phe Bằng tộc giữa bầu không khí đối đầu căng thẳng."},{"chuong":438,"tieuDe":"Nhắm Vào Kim Sí Đại Bằng","tomTat":"Vân Kim Hải dùng cờ xanh cấp Thần Linh phóng kiếm khí và lôi đình tấn công Khổng Cầu Kỷ, nhưng nhờ có Liễu Thần ở bên, Khổng Cầu Kỷ ung dung dùng cánh hoa phá tan mọi thế công, khiến đối phương lầm tưởng thực lực của nó đã gần vượt khỏi cảnh giới Tôn giả. Vân Thương Hải kịp thời ngăn cuộc chiến, sau đó tiếp nhận năm loại thần liệu do tộc trưởng Kim Sí Đại Bằng Kim Loạn Thiên mang tới để hỗ trợ tu bổ trận pháp vượt giới; hai tộc cũng thỏa thuận sẽ liên thủ và tìm kiếm truyền thừa tổ tiên khi lên Thượng giới. Kim Loạn Thiên nhân cơ hội đề nghị để cháu mình là Kim Vân Đằng kết thành đạo lữ với Vân Hi, nhưng Thạch Hạo lập tức dùng bộ pháp mang áo nghĩa Bằng tộc bước tới, nắm tay Vân Hi và công khai nhận nàng là vợ, thậm chí còn cố ý nhắc đến chuyện con cái để chọc giận người Kim Sí Đại Bằng tộc. Kim Vân Đằng suýt mất bình tĩnh khi nhớ lại sự gần gũi giữa hai người tại hoàng đô Hỏa tộc, còn Vân Hi sau khi hoàn hồn liền hất tay Thạch Hạo ra và tức giận trách mắng. Không dừng ở việc phá hỏng hôn sự, Thạch Hạo cùng Khổng Cầu Kỷ quyết định xóa tên Kim Sí Đại Bằng tộc khỏi danh sách được sử dụng trận pháp. Thạch Hạo còn đề xuất biến người của tộc này thành bên thủ lôi, cho phép các Thần sơn giành thêm suất vượt giới bằng cách đánh bại họ, mỗi trận thua sẽ khiến một người Kim Sí Đại Bằng mất quyền lên đường. Khi Vân Kim Hải phản đối vì mang một nửa huyết thống Bằng tộc, Thạch Hạo dọa đưa cả ông ta lên thủ lôi và khẳng định quyền quyết định ai được dùng trận pháp hoàn toàn nằm trong tay phe tu bổ."},{"chuong":439,"tieuDe":"Sắp Loạn","tomTat":"Tại Thiên Thần sơn, Liễu Thần nhận ra nửa dấu chân của một thiên kiêu từng đứng trên đỉnh Thần đạo và nghi rằng tồn tại cấm kỵ ấy có thể đã nhờ trận pháp Thái cổ thoát chết, thậm chí vẫn còn sống trong Hoang Vực. Trong lúc các cường tộc mang thần liệu tới tu bổ trận pháp vượt giới, Thạch Hạo treo thưởng thêm suất cho bất cứ ai đánh bại Kim Bằng, khiến Hống Thiên, một Toan Nghê tán tu và nhiều hậu bối khác liên tiếp ra tay, đẩy Kim Sí Đại Bằng tộc vào cảnh tổn thất nặng nề. Tiểu Tháp từng dụ Thạch Hạo lấy trộm thần liệu để đổi lấy một lần trợ giúp nhưng bị cậu từ chối, còn Liễu Thần cảnh báo cậu và Nhị Ngốc Tử phải mau chóng rời khỏi nơi này. Khi Nhị Ngốc Tử bù đắp trận pháp, dấu chân cổ xưa càng trở nên rõ ràng, để lộ rằng trận pháp không chỉ dùng để vượt giới mà còn đang kêu gọi một tồn tại cấm kỵ, kéo theo nhân quả khó lường. Liễu Thần xác nhận Thiên Nhân tộc có thể rời đi an toàn nhờ quan hệ mật thiết với chủ nhân trận pháp, song vận mệnh của những tộc khác vẫn chưa thể đoán định. Tiểu Tháp thúc giục Thạch Hạo chặt đứt liên hệ với Thiên Thần sơn, đồng thời giúp cậu cảm nhận đại kiếp đang buông xuống và nhìn thấy vết nứt không gian do đại năng Thượng giới thăm dò hạ giới. Trước những dấu hiệu ấy, Thạch Hạo hiểu rằng Hoang Vực sắp bước vào một trận đại loạn đủ sức phá vỡ toàn bộ trật tự cũ."},{"chuong":440,"tieuDe":"Thu Hoạch Khổng Lồ","tomTat":"Trước những dấu hiệu kỳ lạ trên vòm trời, Thạch Hạo truy hỏi về Thượng giới nhưng Tiểu Tháp và Liễu Thần đều tránh tiết lộ, chỉ xác nhận rằng phía trên bầu trời còn tồn tại một thế giới khác. Tiểu Tháp cảnh báo kẻ đi đến tận cùng đại đạo có thể sống qua năm tháng vô tận nhưng phải chứng kiến toàn bộ cố nhân lần lượt qua đời, khiến Thạch Hạo càng thêm trăn trở về tương lai. Theo sự sắp xếp của Liễu Thần, Khổng Cầu Kỷ gặp lại Vân Mộng Lan sau nhiều năm xa cách; bất chấp tu vi đã mất, hai người vẫn nhận ra nhau và nắm tay rời đi trong ánh mắt phức tạp của những người xung quanh. Sau đó, Thạch Hạo hoàn trả pháp khí Thần Linh cho Thiên Thần sơn rồi lấy lý do tu sửa trận pháp trong thôn để yêu cầu các cường tộc cung cấp nhiều loại thần liệu. Khi Vân Thương Hải tiết lộ có một Thần Linh đáng sợ đứng sau nó, các đại tộc không dám phản đối, còn Thạch Hạo lập tức dùng túi càn khôn thu gần một nửa số vật liệu khiến những lão giả có mặt phải vội vàng ngăn cản. Chưa thỏa mãn với thu hoạch ấy, Thạch Hạo tiếp tục mượn danh vị đại nhân bí ẩn để đòi nguyên thủy Chân vũ của Kim Sí Đại Bằng nhằm luyện quạt Ngũ Cầm, làm Kim Loạn Thiên giận dữ nhưng không dám tùy tiện ra tay."},{"chuong":441,"tieuDe":"Rời Đi","tomTat":"Vì e ngại Liễu Thần đứng sau Thạch Hạo, Kim Loạn Thiên đành sai người về bảo khố Bằng tộc lấy Chân vũ Kim Bằng quý hiếm giao cho cậu. Thạch Hạo thử uy lực của Chân vũ, thấy nó có thể làm hư không rung chuyển và phát ra kim quang sắc bén, qua đó thu được vật liệu thứ ba cho kế hoạch luyện chế quạt Ngũ Cầm. Trước nguy cơ đại kiếp giáng xuống, Hỏa Linh Nhi, Cửu Đầu Sư Tử và những người khác muốn trở về báo tin cho bộ tộc, còn Thạch Hạo quyết định ở lại Hoang Vực vì chưa tìm thấy cha mẹ cùng người thân. Nhị Ngốc Tử cũng lựa chọn ở lại đồng sinh cộng tử với Vân Mộng Lan, được Liễu Thần ban cành liễu vàng kim và cho cơ hội đưa một người trở về Thạch thôn. Khi biết khuyên tai Linh Tê của Vân Hi đang nằm trong tay Thạch Hạo, Vân Mộng Lan dựa theo tục lệ Thiên Nhân tộc mà cho phép cậu sau này tới cầu thân, bất chấp Vân Hi cố giải thích rằng tín vật đã bị cướp mất. Thạch Hạo nhân đó xin Vân Thương Hải một số bảo liệu để tu bổ trận pháp Thạch thôn, rồi cùng các đồng bạn rời Thần sơn qua thông đạo hư không do Liễu Thần trực tiếp mở ra. Trên đường trở về, thông đạo chấn động vì một móng vuốt xương khổng lồ vươn lên từ lòng đất, trong khi trên vòm trời xuất hiện khe nứt báo hiệu cường giả Thượng giới đang thử phá tan giới bích."},{"chuong":442,"tieuDe":"Thần Tàng Chí Tôn","tomTat":"Một móng vuốt xám đen khổng lồ bất ngờ hiện ra, khuấy động toàn bộ Đại Hoang và khiến muôn loài khiếp sợ, được Liễu Thần nhận định có liên quan đến Thần tàng Chí Tôn. Tiểu Tháp tiết lộ bảo tàng được dựng trên lưng một con rùa già vô cùng hùng mạnh nên có thể di chuyển dưới lòng đất, nhưng Liễu Thần nghi ngờ cảnh tượng này chỉ là giả tượng do trận pháp tạo thành. Liễu Thần và Tiểu Tháp suy đoán đây là bố cục kéo dài từ thời Thượng cổ, được sắp đặt để dẫn dụ những chí cường giả đang thăm dò Hoang Vực từ Thượng giới. Trở về Thạch thôn, Thạch Hạo từ chối giao số thần liệu quý hiếm cho Tiểu Tháp mà trao toàn bộ cho Liễu Thần nhằm củng cố quê nhà trước đại kiếp. Sau chín ngày, Liễu Thần hoàn thành một đại trận vô thượng kết hợp phòng ngự, tiến công và truyền tống, còn Đả Thần Thạch ăn hết vật liệu thừa rồi xuất hiện dấu hiệu lột xác. Ngay khi đại trận vừa thành, chấn động dữ dội truyền tới từ phương xa, nơi thần quang và những vết nứt không gian đang hội tụ thành một cánh cửa mơ hồ, báo hiệu biến cố lớn sắp giáng xuống."},{"chuong":443,"tieuDe":"Thiên Biến","tomTat":"Cánh cửa vượt giới trên trời bất ngờ nổ tung, trút xuống mưa máu và lân phiến, báo hiệu cuộc tranh đoạt khốc liệt ở Thượng giới đã lan tới Hoang Vực. Những ngày sau đó, hư không liên tục nứt vỡ, dị tượng phủ khắp thiên địa, khiến các Tôn giả phải bỏ trốn hoặc tự phong ấn để tránh đại kiếp. Liễu Thần và Tiểu Tháp giải thích rằng sinh linh Thượng giới bị Đạo tắc ngăn cản, nhưng một số kẻ đáng sợ vẫn có thể dùng bí pháp hạ giới nhằm tranh đoạt di vật và cơ duyên liên quan đến các tồn tại cấm kỵ. Trong lúc khổ tu tại Thạch thôn, Thạch Hạo được khuyên không cần gột rửa thêm mà nên tiếp tục con đường tự khai phá cực hạn; hắn cũng nhiều lần thử mở tấm da thú chứa đại pháp “Lục đạo” và dần cảm nhận được quỹ tích đạo pháp giữa biến động. Quyết tâm tận mắt chứng kiến đại kiếp, Thạch Hạo từ biệt quê nhà, tiếp nhận bảo thuật biến hóa muôn vàn rồi quy nhất do Liễu Thần truyền thụ, trong khi Liễu Thần chuẩn bị đưa cả thôn đi ẩn cư. Sau nửa tháng vượt Đại Hoang tới biên giới phía Tây Thạch quốc, hắn chứng kiến bầu trời bị phá vỡ và một chiếc chuông cổ thần bí giáng xuống, tiếng chuông cùng tế văn vang khắp Hoang Vực. Khi một vật thứ hai tiếp tục hạ xuống từ khe trời, Thạch Hạo lập tức kinh hãi vì dường như đã nhận ra nó."},{"chuong":444,"tieuDe":"Đại Kiếp Nạn","tomTat":"Một thân tháp hai tầng trắng như tuyết hiện ra giữa trời, được Tiểu Tháp xác nhận là phần cơ thể từng thất lạc, nhưng nó không dám tới gần mà lập tức thu liễm khí tức. Tiếp đó, một chiếc chuông lớn và mảnh khay Hỗn Độn không trọn vẹn lần lượt giáng xuống, cùng thân tháp phát tán thần uy để dò xét những tồn tại siêu nhiên khắp Hoang Vực. Nhận ra đại kiếp lần này chỉ có pháp khí hạ giới, Tiểu Tháp chui vào Thế giới hộp báu, tự phong ấn và chìm vào trầm miên để tránh bị phát hiện. Khi đại kiếp chính thức bắt đầu, ba pháp khí chia nhau trấn giữ ba phương, còn vô số ngôi sao xuất hiện giữa ban ngày rồi đồng loạt lao xuống mặt đất như muốn hủy diệt toàn vực. Thạch Hạo lập tức bay lên, định vượt ra vực ngoại để thoát thân, nhưng tận mắt thấy Ly Long bị xích thần trật tự khóa cứng. Ngay sau đó, Bệ Ngạn dù dốc toàn lực thi triển bảo thuật chống trả vẫn bị trói bắt, khiến Thạch Hạo hiểu rằng đường rời khỏi Hoang Vực đã hoàn toàn bị phong tỏa."},{"chuong":445,"tieuDe":"Thần Thánh Như Cỏ Rác","tomTat":"Vô số sao lớn trút xuống Hoang Vực như ngày tận thế, trong khi ba pháp khí trên trời thả xích thần trật tự truy bắt các Tôn giả và Thần Linh ẩn mình. Một giả Thần vừa phá xiềng xích chạy về vực ngoại đã bị lưỡi đao quy tắc chém lìa đầu, còn tiếng nói trong cõi u minh lạnh lùng phủ nhận tư cách Thần Linh của hắn. Hòa vào dòng người tháo chạy, Thạch Hạo nhận ra những ngôi sao xuyên qua chúng sinh mà không gây thương tích, từ đó nhìn thấu đây chỉ là hư cảnh do đạo tắc tạo ra nhằm ép các cường giả lộ diện. Cậu cũng phát hiện chiếc chuông lớn từ Thượng giới đang tra xét những tu sĩ trẻ xuất chúng chạy tới vực ngoại sớm nhất, còn bản thân nhờ thận trọng nên tránh được cuộc sàng lọc. Khi hư cảnh tan biến và mọi người vừa tưởng tai họa đã qua, một thanh mâu đen bất ngờ xuyên thủng ông lão Tôn giả gần Thạch Hạo rồi cuốn xác ông đi. Dư lực của đòn đánh khiến thiếu nữ áo trắng bên cạnh nổ tung, máu nàng văng lên tay Thạch Hạo, khiến cậu phẫn nộ nhận ra đại kiếp thật sự mới bắt đầu và kẻ đứng sau coi thần thánh lẫn chúng sinh như cỏ rác. Ngay sau lời lên án của cậu, một giọng nói lạnh lùng pha ý cười hờ hững mơ hồ vang lên bên tai."},{"chuong":446,"tieuDe":"Dẫn Đạo Nhập Thể","tomTat":"Giữa lúc đại kiếp dùng thần kiếm quy tắc và chiến mâu đen càn quét Tôn giả, Thần Linh khắp Hoang Vực, Thạch Hạo đã nắm lấy cơ duyên hiếm có để bắt giữ những mảnh vỡ đại đạo. Nó dẫn đạo ngấn cùng vô tận phù văn nhập thể, trải qua bốn ngày bốn đêm bị đạo hỏa và đỉnh lô nung luyện, từ đó gột rửa chân thân và xây dựng căn cơ gần gũi với đại đạo dù cảnh giới chưa trực tiếp tăng lên. Khi ba pháp khí trên trời biến mất, Thạch Hạo cưỡng ép đánh thức Tiểu Tháp, nhưng chỉ nhận được lời cảnh báo rằng nguy hiểm mới tạm lắng và Tiểu Tháp vẫn không thể ra tay trợ giúp. Rời nơi tu luyện để dò xét tình hình, nó biết hoàng đô Hỏa Quốc gần như đã bị phá hủy, số phận của Hỏa Linh Nhi và Hỏa Hoàng chưa rõ, còn một chiến trường cổ thần bí đang chống lại ý chí từ trời cao. Tại Thạch Quốc, việc Thạch Hoàng biến mất khiến thiên hạ bất ổn, tạo cơ hội cho Bổ Thiên các, Bất Lão sơn, Tây Thiên giáo cùng nhiều nhóm vực ngoại tiến vào hoàng đô nhằm dựng con rối hoặc chiếm quyền. Từ tin đồn Thượng giới đang mượn tay các thế lực hạ giới tìm kiếm một vật bí ẩn, Thạch Hạo nhận định những kẻ bất hủ vực ngoại có thể là người phát ngôn cho thế lực đứng sau đại kiếp. Phẫn nộ trước âm mưu ấy, nó quyết tiến về hoàng đô, ngăn đối phương thao túng Thạch Quốc và không để vật bí ẩn rơi vào tay họ."},{"chuong":447,"tieuDe":"Tiên Tử Luận Kiếp","tomTat":"Sau đại kiếp, Thạch Hạo trở lại Thạch đô và nhận ra vẻ phồn hoa bên ngoài không che giấu được sóng ngầm do Thạch Hoàng mất tích, trận pháp Thần Linh bị phá và các đại giáo vực ngoại âm thầm nhúng tay. Được Tiểu Tháp xác nhận rằng lối thông giữa hai giới đã khép, nó quyết định tận dụng khoảng trống nguy hiểm này để tiến vào hoàng cung, tìm kiếm những gì Nhân Hoàng có thể đã để lại. Trên đường, Nguyệt Thiền dùng tràng vực cô lập phố xá, khuyên nó thuận theo đại thế và gia nhập Bổ Thiên giáo, nhưng Thạch Hạo kiên quyết từ chối trở thành kẻ phụ thuộc vào người khác. Hai người tới Yên Vũ lâu, phong tỏa gian phòng với ngoại giới rồi đối đáp trong bầu không khí vừa thăm dò vừa đối địch. Nguyệt Thiền tiết lộ rằng sinh linh từ Tôn giả trở lên bị săn giết vì đã trưởng thành đến mức trở thành mục tiêu, còn những sinh linh nhỏ yếu được giữ lại như hạt giống, song đó chỉ là một phần rất nhỏ chứ không phải căn nguyên thật sự của đại kiếp. Không thể thuyết phục Thạch Hạo rời Hạ giới, nàng chuyển sang chất vấn nhận thức của nó về Hoang Vực và tám vực, chuẩn bị vén màn bí mật về bản chất thật sự của vùng đất này."},{"chuong":448,"tieuDe":"Chân Tướng Về Tám Vực","tomTat":"Nguyệt Thiền tiết lộ Thiên, Địa, Huyền, Hoàng, Vũ, Trụ, Hồng, Hoang thực chất là tám nhà tù, còn sinh linh nơi đây bị Thượng giới xem như hậu duệ của những kẻ từng phạm trọng tội. Thạch Hạo không chấp nhận việc con cháu đời đời gánh tội tổ tiên, nghi ngờ lịch sử đã bị che giấu và tuyên bố nếu muốn lên Thượng giới thì sẽ tự tìm đường thay vì cầu xin sự công nhận. Nguyệt Thiền thừa nhận nàng vốn đến từ Thượng giới, được đưa xuống từ nhỏ để trải qua rèn luyện, khiến Thạch Hạo càng chú ý đến nguồn gốc và mục đích của các đạo thống như Bổ Thiên giáo, Bất Lão sơn. Mâu thuẫn bùng nổ tại Yên Vũ lâu khi Thạch Hạo dùng phù quang cùng tràng vực mười Động Thiên trấn áp, còn Nguyệt Thiền dùng Ngọc Kiếm phá vỡ không gian phong kín, làm gian phòng và nhiều trận pháp xung quanh tan rã. Đúng lúc giao chiến quyết liệt, Thạch Hạo cảm nhận khí tức Hoàng đạo và long khí cuồn cuộn từ hoàng cung, nhận ra đó là dị tượng do vật Thạch Hoàng để lại nên lập tức chuyển hướng. Một thanh niên áo tím mới gia nhập Bổ Thiên giáo bất chấp lời ngăn cản của Nguyệt Thiền mà đánh lén, nhưng Thạch Hạo chỉ phóng hai tia chớp từ mắt đã đánh rơi bảo cụ rồi tiếp tục tiến về hoàng cung để tìm hiểu di vật bí ẩn."},{"chuong":449,"tieuDe":"Xông Vào","tomTat":"Thạch Hạo trở lại Thạch đô giữa lúc cuộc tranh đoạt quyền kế thừa Thạch Quốc khiến các phe căng thẳng, đồng thời cảm nhận long khí hóa Chân Long trong hoàng cung có liên hệ với mình. Trên đường tiến cung, nó bị một đạo sĩ trung niên dùng Đạo thư màu tím dựng trận phong tỏa, còn những người từ phủ Hoang Thiên hầu đến trợ giúp cũng không thể phá giải. Thạch Hạo vận dụng kiếm ý cọng cỏ và kiếm gãy phá trận, chém đầu đạo sĩ; khi Đạo thư hấp thu tinh huyết và bùng phát khí tức Thần Linh, long khí từ hoàng cung lập tức đánh nát pháp khí ấy. Phát hiện Nguyệt Thiền đang quan sát, Thạch Hạo công khai khiêu khích nàng, báo hiệu một trận sinh tử khó tránh khỏi giữa hai người. Sau đó, nó tiếp tục giết bốn Vương giả chặn đường và mang theo đầu của họ tiến thẳng tới hoàng cung, khiến toàn thành kinh hãi. Tại cửa cung, một chiến tướng phủ nhận mệnh lệnh của Thạch Hoàng rồi huy động pháp tiễn cùng đại trận đã hư hại để ngăn cản, nhưng một thị vệ kịp thời công bố chiếu thư cho phép Thạch Hạo vào cung, buộc quân phòng thủ phải lui lại."},{"chuong":450,"tieuDe":"Thần Uy Của Hoang Thiên Hầu","tomTat":"Thạch Hạo được các lão nhân phủ Hoang Thiên hầu và thị vệ già tháp tùng tiến sâu vào hoàng cung Thạch Quốc, nơi khí vận Hoàng đạo hội tụ và cục diện kế vị đang bị nhiều thế lực nhòm ngó. Khi gặp Tần Dũng của Bất Lão sơn tại ngọc trì, nó nhận ra lời triệu kiến không phải do Thạch Hoàng lưu lại, đồng thời phát hiện đại giáo vực ngoại đã công khai can thiệp triều chính và mưu toan dựng Hoàng đế con rối. Thạch Hạo lập tức quay lại cửa cung, cho quân lính một cơ hội rút lui rồi dùng Chí Tôn cốt áp chế, phong ấn hồ lô máu cấp Thánh khí của chiến tướng phản nghịch. Sau khi đoạt pháp bảo, nó chém đôi chiến tướng và thi triển pháp môn Côn Bằng tiêu diệt toàn bộ những kẻ vẫn cố tình chống đối, nhưng tha cho những người đã kịp lui bước. Tần Dũng đề nghị giúp Thạch Hạo lên ngôi với điều kiện nó phải phục vụ Bất Lão sơn, song bị cự tuyệt và buộc phải tạm rút lui trước sự uy hiếp của hồ lô máu. Cuối cùng, Thạch Hạo tiến đến trung ương Thiên cung, công khai ra lệnh cho cường giả vực ngoại rời khỏi cấm địa hoàng gia và cảnh cáo các vương hầu đang dao động phải quay đầu, nếu không sẽ bị giết không tha."},{"chuong":451,"tieuDe":"Uy Áp Các Vương","tomTat":"Thạch Hạo bước lên vị trí cao nhất của trung ương Thiên cung, lấy chiến tích bất bại và pháp chỉ của Thạch Hoàng làm thế áp đảo quần hùng đang tranh quyền tại Thạch Quốc. Khi có kẻ châm chọc phong hiệu của hắn, Chiến Vương cùng các thị vệ già công khai xác nhận Hầu phủ đã được đổi thành Vương phủ, để hắn chính thức được xưng là Hoang Thiên Vương. Thạch Hạo lập tức trấn sát người áo xanh ẩn trong đám đông, chém đôi một Chiến tướng thất trách và dùng lôi điện thiêu chết tu sĩ vực ngoại tự tiện xâm nhập cấm cung. Hắn tiếp tục chất vấn Vũ tộc, Côn Vương và Lan Vương về việc đưa nhân mã Bổ Thiên giáo, Bất Lão sơn cùng Tây Thiên giáo vào hoàng cung, bác bỏ lý lẽ bảo vệ cơ nghiệp và kết tội họ dẫn sói vào nhà, phản quốc nhục quốc. Khi hắn ép tới phe Vương hầu đối địch, một kỳ tài Bổ Thiên giáo cầm kim giản và một thanh niên Tây Thiên giáo cầm bình bát đồng thời dùng hai Thánh khí chắn đường. Bất chấp sự uy hiếp ấy, Thạch Hạo không chịu lùi bước và ra tối hậu thư rằng mọi tu sĩ vực ngoại không rút khỏi hoàng cung đều sẽ bị giết sạch."},{"chuong":452,"tieuDe":"Ai Cùng Tranh Phong","tomTat":"Thạch Hạo tiến về phía các Vương hầu đối địch, mỗi bước đều sinh sen vàng và hào quang, thể hiện cảnh giới thân thể gần Đạo khiến toàn trường kinh hãi. Hắn chém giết những người Vũ tộc, dùng chuỗi sét phá hủy pháp khí hộ thân của Côn vương, rồi lần lượt hóa giải Dẫn Long thủ, chuông thần và Kim Cương Bất Hoại thân của hai kỳ tài đến từ Bổ Thiên giáo và Tây Phương giáo. Sau khi tiêu diệt toàn bộ thủ hạ của Côn vương và Lan vương, Thạch Hạo dùng lôi điện biến hai kẻ cầm đầu thành tro bụi, đồng thời lấy hồ lô đỏ trấn áp hai kỳ tài vực ngoại dù Thánh khí của họ đã được một người bí ẩn thu hồi. Ba Vương hầu ngoài miệng nhận sai nhưng vẫn ngầm nuôi ác ý cũng bị hắn dùng pháp môn Côn Bằng đánh chết, buộc những kẻ từng cấu kết với thế lực vực ngoại phải cúi đầu tuyên bố rút lui. Giữa lúc quần Vương không ai dám cản đường, Thạch Hạo cảm nhận sự cộng hưởng với vật mà Thạch Hoàng để lại và đi thẳng tới trung tâm Thiên cung. Nguyệt Thiền tiên tử, một thanh niên mặc áo tang của Tây Phương giáo và một thanh niên thuộc Bất Lão sơn đồng thời tiến đến, khiến khí tượng quanh cung điện biến đổi. Thạch Hạo quay lại nhìn ba đối thủ, để chiến ý cùng thánh hà bùng lên quanh thân rồi chậm rãi bước vào Thiên cung hoàng kim."},{"chuong":453,"tieuDe":"Trung Ương Thiên Cung","tomTat":"Thạch Hạo tiến vào Trung Ương Thiên Cung, nơi long khí tổ tiên và quốc vận Thạch quốc lập tức hội tụ quanh nó, cho thấy tòa thiên cung đã thừa nhận người kế vị. Tại nội điện, nó gặp Thập cửu hoàng tử Thạch Sùng, tuyên bố sẽ tiêu diệt bất cứ kẻ nào cam tâm làm con rối cho đạo thống vực ngoại, rồi dùng Côn Bằng quyền đánh bại bảo thuật Bệ Ngạn cùng các linh thân hung thú của đối phương. Sau trận đấu, Thạch Sùng thừa nhận mình không thích hợp kế vị và kích hoạt trận pháp thần linh, ngăn Nguyệt Thiền, Tần Lôn và Trượng Lục hợp sức trấn áp Thạch Hạo. Được quốc vận mở đường tới bảo tọa Nhân Hoàng, Thạch Hạo phát hiện ngọc tỷ đã vỡ, trận pháp bị tàn phá và vô số dấu vết đại chiến, đồng thời biết Thạch Hoàng đã mất tích, rất có thể bị bắt đi. Khi cường giả Bổ Thiên giáo, Bất Lão sơn và Tây Phương giáo kéo đến hình thành vòng vây, Thạch Hạo ngồi lên bảo tọa, sẵn sàng nghênh chiến. Đúng lúc sát cục sắp bùng nổ, hư không trước mặt nó phát sáng và hóa thành một cánh cửa thế giới lưu chuyển khí lành."},{"chuong":454,"tieuDe":"Nhân Hoàng Thạch Hạo","tomTat":"Thạch Hạo tiến vào tiểu thế giới bí mật của Thạch Hoàng, một không gian tối tăm và rạn nứt đang bên bờ tan rã, trong khi cao thủ tam giáo phong tỏa Trung ương Thiên cung để chờ vây giết hắn. Tại đây, Nhân Hoàng ấn chân chính của Thạch quốc từ lòng đất bay lên, chủ động dùng long khí và khí lành che chở hắn; Đả Thần Thạch sau hai lần bị đánh văng cũng nhận ra bảo ấn là thạch thai do một tiền bối thành Thần để lại. Tiểu Tháp giải thích quốc bảo này đã tích tụ tín ngưỡng, bí lực và số mệnh của Thạch quốc qua nhiều đời, đủ giúp Thạch Hạo lập tức bước vào cảnh giới Tôn giả. Tuy nhiên, nhớ lời cảnh báo của Liễu Thần về nguy cơ làm tổn hại căn cơ quốc thổ, Thạch Hạo kiên quyết từ chối luyện hóa nguồn sức mạnh ấy. Từ sự bảo hộ của vận nước, Tiểu Tháp suy đoán Thạch Hoàng chưa chết mà chỉ trọng thương rồi rời khỏi Hoang Vực, đồng thời xác nhận việc Nhân Hoàng ấn gia trì cho Thạch Hạo chính là dấu hiệu truyền ngôi. Mang bảo ấn trở lại Trung ương Thiên cung, Thạch Hạo thản nhiên ngồi lên bảo tọa trước vòng vây của Nguyệt Thiền, Tần Lôn, Trượng Lục và các cao thủ tam giáo. Khi những kẻ đối địch buộc tội hắn mưu phản soán vị, di chiếu của Thạch Hoàng hiện ra giữa ánh vàng, công khai xác lập Thạch Hạo là người kế vị Nhân Hoàng."},{"chuong":455,"tieuDe":"Ngôi Vị Hoàng Đạo","tomTat":"Pháp chỉ của Thạch Hoàng xuất hiện trên bầu trời Thạch đô, chính thức truyền ngôi cho Thạch Hạo, khiến muôn dân quỳ lạy và đồng thanh suy tôn tân Nhân Hoàng. Dân tâm cùng khí vận quốc gia nhanh chóng hóa thành long khí Hoàng đạo, cộng hưởng với bảo ấn Nhân Hoàng và gia trì cho hắn trên bảo tọa giữa Thiên cung. Nhận thấy Thạch Hạo đã được Hoàng đạo thừa nhận, cường giả các đại giáo liên tục vu cáo hắn soán vị để phá hỏng nghi lễ kế vị. Thạch Hạo ngồi yên trên ngai, điều khiển bàn tay Hoàng đạo xuyên qua trận pháp Thần Linh, nghiền nát mọi bảo cụ và thần thông rồi giết sạch hơn mười kẻ phản đối do trưởng lão Bổ Thiên giáo dẫn đầu. Khi Nguyệt Thiền chất vấn hắn có thể giữ đế vị được bao lâu giữa đại thế hỗn loạn, hắn thản nhiên đáp trả rằng bên mình còn thiếu một hầu gái, khiến Chiến vương lớn tiếng tán thành. Trước sự phẫn nộ của các trưởng lão Bất Lão sơn và Tây Phương giáo, tân hoàng tuyên bố bất kỳ kẻ nào xâm phạm Hoàng cung và quốc vận Thạch quốc đều phải bị tiêu diệt. Pháp chỉ lại cộng hưởng với tiếng tung hô của dân chúng, giúp Thạch Hạo hòa cùng đại thế thiên địa nơi Hoàng cung và bắt đầu trấn áp toàn bộ cường giả bốn phía."},{"chuong":456,"tieuDe":"Đại Chiến Chốn Hoàng Cung","tomTat":"Thạch Hạo chính thức được khí vận Thạch Quốc và thần ấn quốc bảo thừa nhận, long khí Hoàng đạo hóa thành thiên long hữu hình quanh thân, giúp hắn xác lập uy thế của tân Nhân Hoàng. Không ẩn mình trong trận pháp bảo vệ Thiên cung, hắn chủ động bước ra nghênh chiến và dùng long khí đánh vỡ hàng loạt pháp khí, trấn sát hàng chục trưởng lão cùng Vương hầu thuộc phe ba giáo. Trước Khổng Tước bảo thuật của Tần Lôn, Thạch Hạo thi triển pháp môn Côn Bằng, khiến đạo cốt đối phương chấn động và lòng tin bắt đầu dao động. Hắn tiếp tục diễn hóa một cây cỏ thành kiếm giới, ép Trượng Lục vận dụng thần thông vô lượng cùng Bất Hoại Thân nhưng vẫn bị đánh bay. Sát trận do Nguyệt Thiền tiên tử kích hoạt cũng bị trận văn Hoàng cung đã thông linh phản kích và phá hủy hoàn toàn. Nguyệt Thiền sau đó cầm bảo ấn trực tiếp áp sát, phối hợp với Tần Lôi và Trượng Lục vây công, song Thạch Hạo vẫn bình tĩnh lấy một địch ba. Khi long khí Hoàng đạo lại bùng lên như thiên long mở đường, thêm hàng chục địch nhân chết trước Thiên cung, khiến toàn trường chấn động trước uy thế của Tiểu Thạch trên cương vị Nhân Hoàng."},{"chuong":457,"tieuDe":"Uy Nghiêm Của Hoàng Đạo","tomTat":"Vừa kế vị Nhân Hoàng, Thạch Hạo đã một mình đối đầu Trượng Lục, Tần Lôn và Nguyệt Thiền, lần lượt dùng quyền ấn, Chu Tước bảo thuật và kiếm đạo cọng cỏ chống lại thần thông của ba đại nhân kiệt. Trong khi cuộc chiến giằng co, Túc vương cấu kết với tu sĩ ba giáo, định phá trận văn hoàng cung và phong tỏa Ngọc Hoa môn để triệt tiêu lợi thế của tân hoàng. Chiến vương cùng các Vương hầu trung thành, thị vệ và người của Hoang Thiên vương phủ muốn ngăn cản, nhưng Thạch Hạo lấy uy quyền Nhân Hoàng ra lệnh cho tất cả lui lại. Nó chủ động dùng trận chiến hiểm nghèo để tôi luyện bản thân, đồng thời nhận được quốc vận, sự kính ngưỡng của muôn dân và bảo ấn Hoàng đạo liên tục gia trì. Nhờ long khí ngày càng hùng hậu, Thạch Hạo đánh văng Trượng Lục, chém đứt một lọn tóc sát cổ Nguyệt Thiền, khiến ba thiên kiêu liên thủ vẫn dần rơi vào thế bất lợi. Cuối cùng, nó bùng phát uy thế Hoàng đạo, đánh bật cả ba cao thủ rồi lao thẳng vào đội hình Túc vương và tu sĩ ba giáo, mở màn cho một trận huyết chiến trong hoàng cung."},{"chuong":458,"tieuDe":"Ba Giáo Thất Bại Thảm Hại","tomTat":"Sau khi đạt chính quả Hoàng đạo, Thạch Hạo phá tan vòng vây của Nguyệt Thiền, Tần Lôn và Trượng Lục rồi lao vào tàn sát đội ngũ tu sĩ ba giáo. Phe địch huy động ba thánh khí hợp lực trấn áp, nhưng long khí cùng quần thể bảo điện trong hoàng cung đã cắt đứt sự điều khiển của họ, giúp Thạch Hạo thi triển Côn Bằng pháp và thần thông ba đầu sáu tay để phản công. Hắn đánh bật ba đại cao thủ, truy sát và giết Túc vương cùng những Vương hầu phản loạn, đồng thời ra lệnh cho Chiến vương phong tỏa Hoàng Đô và mở đại trận hộ thành. Nguyệt Thiền, Tần Lôn và Trượng Lục lần lượt dốc toàn lực thi triển Bổ Thiên thuật, thần thông Ngũ Hành và Thế Giới Thần Thông, song vẫn không thể áp chế Thạch Hạo, thậm chí Tần Lôn còn bị đánh trọng thương. Thạch Hạo tạm bỏ qua ba người để quét sạch thuộc hạ của họ, khiến hàng trăm tu sĩ tử trận, gần một ngàn người hoảng loạn và toàn bộ đội hình liên quân tan vỡ. Ba đại cao thủ buộc phải rút khỏi hoàng cung, che chở nhân mã chạy trốn, nhưng Thạch Hạo tiếp tục truy sát khiến lực lượng Tây Phương giáo và Bất Lão sơn gần như bại vong. Sau cùng, hắn chuyển mục tiêu sang Bổ Thiên giáo, đuổi kịp đoàn người của Nguyệt Thiền và ra tay định bắt giết họ."},{"chuong":459,"tieuDe":"Lục Thần Trận","tomTat":"Thạch Hạo vận dụng long khí Hoàng đạo tiêu diệt hơn hai mươi tu sĩ Bổ Thiên giáo, nhưng Nguyệt Thiền dùng thần thông trong đôi mắt phá vòng vây và thoát khỏi Thạch đô. Trong lúc Chiến vương cùng các Vương hầu trung thành phong tỏa Hoàng thành, Thạch Hạo thi triển pháp môn Côn Bằng truy đuổi nàng suốt hơn ba nghìn dặm và nhận ra nàng nắm giữ Súc Địa Thành Thốn. Tại một linh hồ, Nguyệt Thiền lợi dụng việc long khí Hoàng đạo của hắn suy yếu để giao chiến bằng bảo thuật Chân Long, qua đó dẫn dụ hắn tiến vào sát cục đã chuẩn bị từ trước. Nàng kích hoạt Lục Thần trận, điều động lôi điện cùng sức mạnh núi sông oanh kích dữ dội, khiến pháp khí thượng cổ của Thạch Hạo bị phá hủy và thân ảnh hắn biến mất. Sau một canh giờ vận chuyển lôi trận, Nguyệt Thiền không còn cảm nhận được khí tức của đối thủ nên cho rằng hắn đã hóa thành tro. Tuy nhiên, khi nàng tiến vào vùng đất cháy đen kiểm tra, một miếng đồng thau bất ngờ mở ra thông đạo màu vàng, từ đó một bàn tay lớn vươn ra chụp lấy eo nàng rồi kéo đi."},{"chuong":460,"tieuDe":"Bắt Tiên Tử","tomTat":"Nhờ ẩn náu trong Thế giới Hộp quý, Thạch Hạo sống sót qua Lục Thần trận rồi bất ngờ xuất hiện, ôm chặt eo Nguyệt Thiền và định kéo nàng vào tiểu thế giới để trấn áp. Nguyệt Thiền thi triển Bổ Thiên thuật làm thời không hỗn loạn, thoát khỏi thế khống chế, sau đó tiếp tục quyết chiến với Thạch Hạo bằng Ngọc kiếm, thần thông ngân hà và tổ hợp bảo thuật Chân Long–Thần Hoàng. Thạch Hạo dùng pháp môn Côn Bằng cùng kiếm ý cọng cỏ đối kháng, giao chiến hơn năm trăm hiệp và khiến mi tâm nàng chảy máu, nhưng cả hai cũng hao tổn nghiêm trọng. Khi tàn dư Lục Thần trận tự diễn hóa thành sát trận mới, triệu hồi vô số khối đá oanh kích như thiên thạch, Thạch Hạo buộc phải kích phát Chí Tôn cốt đã niết bàn tái sinh. Thần quang từ ngực hắn phá tan thế công, áp đảo hơn mười loại bảo thuật và nhiều lần thi triển Bổ Thiên thuật của Nguyệt Thiền, cuối cùng giam giữ rồi phong ấn nàng trong Thế giới Hộp quý. Tuy bắt được tiên tử Bổ Thiên giáo, Thạch Hạo cũng hộc máu vì sức phản chấn và sự tiêu hao khủng khiếp của Chí Tôn cốt."},{"chuong":461,"tieuDe":"Phá Của","tomTat":"Sau khi chịu thương tổn nặng từ sát trận của Nguyệt Thiền, Thạch Hạo vận chuyển cốt văn, uống rượu Hầu Nhi và dùng linh dược để ổn định Chí Tôn cốt mới niết bàn, khôi phục thần lực cùng tinh lực. Biết việc bắt giữ truyền nhân Bổ Thiên giáo sẽ chấn động tám vực và dẫn dụ cường giả tới điều tra, nó quyết định dựng một sát trận tại chiến trường cháy đen để phục kích viện binh. Tiểu Tháp không chịu giúp miễn phí, nhưng Đả Thần Thạch đồng ý trao một trận đồ đáng sợ với điều kiện được đặt cạnh ngọc tỷ; do vật liệu quá quý hiếm, Thạch Hạo chỉ bố trí một phần và điều chỉnh để trận pháp chuyên nhắm vào tu sĩ từ Tôn giả trở lên. Khi trở lại Hoàng đô lúc bình minh, nó được quân dân tung hô là Nhân Hoàng và cảm nhận rõ long khí cùng số mệnh hoàng triều gia trì. Sau khi kiểm tra tình hình các tu sĩ đối địch bị giam lỏng, Thạch Hạo tiến vào bảo khố và bí mật giao Chiến Vương danh sách vật liệu cần thiết. Nó tạo chứng cứ ngoại phạm bằng cách để Chiến Vương tuyên bố mình vẫn ở trong bảo khố, rồi âm thầm quay lại vùng đất tai ương bố trí cạm bẫy. Hoàn tất trận pháp, Thạch Hạo xóa những dấu vết bất lợi, cố ý để lại manh mối dẫn người điều tra tới chân tướng giả, sau đó hóa thành Kim Bằng bay về Hoàng đô."},{"chuong":462,"tieuDe":"Bảo Tàng Hoàng Cung","tomTat":"Sau khi kế vị Nhân Hoàng, Thạch Hạo trở lại hoàng cung giữa tiếng tung hô của dân chúng và bí mật cho Chiến vương biết Nguyệt Thiền đã bị giữ làm hầu gái, nhưng đồng ý tạm thời không để nàng lộ diện nhằm tránh kích động Bổ Thiên giáo. Khi kiểm tra cung thành, nó phát hiện hơn nửa thần trận Thượng cổ đã bị phá hủy trong đại kiếp, còn Thạch Hoàng và Thống lĩnh thị vệ có thể đã đi qua một thông đạo hư không tới Thượng giới. Ngự Hoa viên cùng ngoại khố gần như bị cướp sạch bởi tu sĩ ba giáo và những Vương hầu, hoàng tộc cấu kết với thế lực vực ngoại, khiến Thạch Hạo quyết định bắt các phe phản nghịch phải trả giá. Nhờ Hoàng ấn, nó mở được nội khố bí mật và tìm thấy lượng lớn thần liệu, pháp khí cùng báu vật đủ để hỗ trợ phục dựng hệ thống phòng vệ hoàng cung. Thạch Hạo dự định phối hợp bốn pháp kiếm Thần Linh với một trận pháp siêu cấp trước cửa cung, đồng thời thu lấy cây chiến kích Thần Linh được luyện phỏng theo kích Thiên Hoang của Côn Bằng. Rời nội khố với thu hoạch vượt xa mong đợi, nó theo Chiến vương hướng tới Kinh Văn lâu và Bảo Thuật điện, hai nơi chứa đựng những truyền thừa mà nó khao khát nhất."},{"chuong":463,"tieuDe":"Điển Miếu","tomTat":"Thạch Hạo cùng Chiến Vương và một thị vệ lớn tuổi đi sâu vào hoàng cung, tiến đến Điển miếu, nơi lưu giữ kinh văn và bảo thuật trọng yếu của Thạch quốc. Vừa đặt chân lên bậc thềm, hắn đã cộng hưởng với khí tức đại đạo do các đời Nhân Hoàng lưu lại, bước vào trạng thái ngộ đạo và cô đọng những cảm悟 thu được trong đại kiếp nạn. Khi kiểm tra kho tàng, Thạch Hạo phát hiện nhiều cốt thư, ngọc cốt cùng các bức họa truyền thừa quý giá đã bị hoàng thân lấy mất sau biến cố, đồng thời biết rằng ba bảo thuật trấn quốc đều đã thất truyền hoặc khiếm khuyết ở những mức độ khác nhau. Trong tĩnh thất của Nhân Hoàng, hắn vận chuyển Hoàng ấn, vô tình kích hoạt dấu ấn Toan Nghê ẩn trên vách đá và ghi nhớ trọn vẹn môn bảo thuật Thiên giai hoàn chỉnh. Dù có thể lập tức nghiên cứu truyền thừa mới, Thạch Hạo quyết định ưu tiên thanh toán những chiến tướng và vương hầu phản bội, đồng thời chuẩn bị thu hồi các đại thần thông hoàng tộc đang phân tán. Sau đó, hắn nhớ tới Nguyệt Thiền tiên tử, dùng miếng đồng thau mở thông đạo vàng dẫn vào tiểu thế giới nơi nàng vẫn bị giam giữ."},{"chuong":464,"tieuDe":"Đồ Cầm Thú","tomTat":"Tiến vào tiểu thế giới trong hộp báu đồng thau, Thạch Hạo bắt gặp Nguyệt Thiền đang hứa hẹn thần liệu của Bổ Thiên giáo để mua chuộc Tiểu Tháp trấn áp hắn, còn Tiểu Tháp nhân cơ hội nâng giá và kỳ kèo đòi lợi ích. Đả Thần Thạch vô cớ bị cuốn vào cuộc mặc cả, sau đó lại giả vờ xin Nguyệt Thiền thần liệu thuộc tính Thổ nên liên tiếp bị đánh văng. Xem Nguyệt Thiền là tù binh, Thạch Hạo bác bỏ những lời dụ dỗ về bảo khố Bổ Thiên giáo, lục soát lấy ra ngọc kiếm, bảo dược cùng các vật dụng nàng mang theo, nhưng không giữ thanh kiếm quý. Hắn còn ép nàng giao ra đại pháp Chân Long hoặc thần thông của Bổ Thiên giáo, nếu không sẽ giữ nàng lại làm hầu gái, khiến vị thánh nữ vốn điềm tĩnh cũng phải hoảng sợ. Trở về hoàng cung, Thạch Hạo cùng Chiến Vương và các thị vệ chuẩn bị tu sửa đại trận thần linh để đối phó nguy cơ sắp tới. Trong lúc hắn thể ngộ Nhân Hoàng ấn, bảo ấn bất ngờ phóng ra long khí, tự điều động thần liệu và sau ba ngày đã hoàn thành đại trận với bốn thanh pháp kiếm thần linh trấn giữ bốn hướng. Có được phòng tuyến mới, Thạch Hạo mong nhân mã ba giáo kéo đến thật đông để đại trận thể hiện uy lực."},{"chuong":465,"tieuDe":"Thiết Huyết Sát Phạt","tomTat":"Nhờ Nhân Hoàng ấn, Thạch Hạo khôi phục gần chín thành hệ thống đại trận thần linh trong hoàng cung, dù việc này gần như vét sạch số thần liệu quý hiếm trong bảo khố. Lo bí mật trận pháp cũ đã bị các vương hầu và hoàng tộc phản loạn tiết lộ, nó cho đảo lộn ngũ hành, dịch chuyển trận vị và thay đổi toàn bộ kết cấu phòng thủ. Sau đó, Thạch Hạo mở cuộc thanh trừng quân đội, hành quyết những chiến tướng từng dẫn tu sĩ ba giáo vào cung nhưng tha cho các binh sĩ không trực tiếp tham gia phản loạn. Tại Chu Tước doanh, chỉ huy phản loạn dựa vào cao thủ, Thánh khí và đại trận do Bất Lão sơn để lại để chống cự, song phòng tuyến nhanh chóng bị phá và hắn bị Thạch Hạo dùng pháp kiếm thần linh chém đầu. Chỉ trong nửa ngày, mười ba chiến tướng phản quốc bị giết, các quân doanh được ổn định và binh quyền được giao lại cho những vương hầu đáng tin cậy. Chiến Vương, vị thống lĩnh thị vệ cùng các cường giả cấp Vương tiếp tục tịch biên phủ đệ của những kẻ mưu phản, vừa diệt trừ hậu họa vừa bổ sung quốc khố. Khi thế cục Thạch Đô đã nằm trong tầm kiểm soát, Thạch Hạo đích thân tiến đến Vũ Vương Phủ, quyết xóa bỏ bộ tộc này."},{"chuong":466,"tieuDe":"Vũ Tộc Diệt","tomTat":"Thạch Hạo khoác chiến y vàng, dẫn quân Thạch Quốc bao vây Vũ Vương phủ và tuyên bố chỉ trừng trị những kẻ chủ mưu, nhưng phe chủ chiến của Vũ tộc vẫn cự tuyệt đầu hàng. Mọi nỗ lực dùng tế đàn mở đường đào thoát đều thất bại vì Thạch đô đã bị đại trận hộ thành và tế đàn hoàng tộc phong tỏa. Theo lệnh Thạch Hạo, quân triều đình phá tan trận pháp phòng hộ, san phẳng phần lớn phủ đệ, song bị Vũ đạo cửu trùng thiên cùng bí pháp mưa sấm của Vũ tộc chống trả quyết liệt. Thạch Hạo đích thân rút pháp kiếm thần linh, chém nát hoa sen đang liên tục lột xác, khiến nhiều cường giả Vũ tộc bị diệt và phòng tuyến cuối cùng sụp đổ. Trong thần miếu, Vũ Vương dùng pháp chỉ cùng tượng đá Vũ Thần liều chết phản công, nhưng pháp chỉ bị chém vụn, còn tượng đá bị thần kích trấn quốc xuyên thủng rồi kéo ngược trở lại đánh nổ lão. Tượng thần và thần miếu cùng bị hủy, Thạch Hạo giao phần còn lại cho hai Vương hầu xử lý; đến cuối ngày, toàn bộ cường giả Vũ tộc đã bỏ mạng, chỉ phụ nữ và trẻ nhỏ được tha."},{"chuong":467,"tieuDe":"Chiêu Cáo Thiên Hạ","tomTat":"Sau khi Vũ tộc cùng các thế lực phản loạn bị tiêu diệt, Thạch Hạo hoàn toàn khống chế Hoàng đô và truyền pháp chỉ kế vị của tiên hoàng tới khắp Thạch Quốc. Hơn phân nửa thành trì nhanh chóng quy thuận, khiến quốc vận hội tụ thành tám mươi mốt thiên long quanh tân Nhân Hoàng, đủ giúp cậu đột phá Tôn giả và giao chiến với cường giả cảnh giới này tại kinh đô. Tuy nhiên, Thạch Hạo từ chối luyện hóa long khí vì không muốn dựa vào ngoại lực, bị ràng buộc với quốc vận hay thu hút sự truy sát từ Thượng giới. Trong lúc tìm vật liệu tu bổ Bất Diệt Kim Thân, cậu gặp lại lão già từng trực tiếp móc Chí Tôn cốt của mình năm xưa và lạnh lùng ra lệnh thẩm vấn rồi xử chém. Sau đó, Bất Diệt Kim Thân dung hợp một khối vật chất linh tính bí ẩn, sinh ra khí tức gần như có sự sống; Tiểu Tháp nhận ra đó là Vạn Pháp thạch quý hiếm, có thể thúc đẩy pháp khí lột xác và tấn cấp. Thạch Hạo tiếp tục tìm bảo vật, nghiên cứu pháp thuật để chuẩn bị cho sóng gió, và năm ngày sau, tu sĩ ba giáo tiến vào Hoàng đô."},{"chuong":468,"tieuDe":"Tu Sĩ Ba Giáo","tomTat":"Tu sĩ ba giáo nhanh chóng tiến vào Thạch đô nhưng chỉ tạm thời trú lại, còn Thạch Hạo ra lệnh cho quân đội án binh bất động vì nhận ra các Chí Cường giả thực sự vẫn đang quan sát từ ngoài thành. Trượng Lục thay mặt Tây Phương giáo tới chuyển lời, kịp thoát khỏi bàn tay long khí hoàng đạo của Thạch Hạo và để lại đề nghị dốc sức ủng hộ hắn để đổi lấy sự trợ giúp tìm kiếm một vật bí ẩn trong tương lai. Khi Bằng Cửu báo rằng một số hoàng tử, công chúa đang liên hệ với ba giáo để tranh ngôi, Thạch Hạo quyết định cho họ tự lựa chọn con đường và tự gánh lấy hậu quả. Sứ giả Tần Lĩnh của Bất Lão sơn sau đó tiết lộ cha mẹ Thạch Hạo đang ở thế lực này, có khả năng tiến vào Thượng giới, đồng thời cho biết hắn đã có một người em trai thiên tư xuất chúng. Không thể moi thêm nguyên nhân cha mẹ chưa trở về hay tung tích tổ phụ, Thạch Hạo để Tần Lĩnh rời đi rồi trầm mặc suốt đêm trước những tin tức bất ngờ về gia đình. Sáng hôm sau, một nữ đạo sĩ của Bổ Thiên giáo đến ngoài Hoàng thành, ngang ngược bắt Nhân Hoàng phải đích thân ra nghênh đón và buông lời xúc phạm, khiến Thạch Hạo lập tức lên tiếng chất vấn sự vô lễ của bà ta."},{"chuong":469,"tieuDe":"Chiến Tôn Giả","tomTat":"Một đạo cô trung niên đại diện Bổ Thiên giáo đến Hoàng đô, công khai gọi Thạch Hạo là “tiểu Thạch” rồi phóng uy áp Tôn giả để áp chế quân phòng thủ. Thạch Hạo phá tan sóng bạc, mặc chiến y bước ra khỏi Hoàng cung và thẳng thừng bác bỏ thái độ bề trên của sứ giả. Dù mới ở Liệt Trận cảnh, hắn mượn long khí Hoàng đạo và số mệnh Thạch quốc để giao chiến ngang ngửa với đối phương, trong khi trận pháp Hoàng đô ngăn dư chấn tàn phá thành trì. Pháp kiếm thần linh lần lượt hóa giải ánh đao bạc và chém đứt phất trần, buộc đạo cô phải để lộ mục đích thật sự là dò hỏi tung tích Nguyệt Thiền. Khi bà ta lấy Huyền thuẫn do một lão rùa Thần Đạo lưu lại để phòng ngự, Thạch Hạo vẫn dùng kiếm chém nứt món pháp khí vốn được coi là kiên cố không thể phá. Hắn tiếp tục tung kiếm khí chém rơi một cánh tay của đạo cô, khiến vị Tôn giả kinh hãi vì bị một thiếu niên gây trọng thương ngay trước Hoàng đô."},{"chuong":470,"tieuDe":"Một Quẻ Đoạn Sinh Tử","tomTat":"Đạo cô trung niên của Bổ Thiên giáo tháo chạy khỏi Hoàng đô nhưng vẫn bị Thạch Hạo dùng long khí Hoàng đạo truy sát, đánh nát mai rùa Thần Đạo và khiến bà trọng thương. Khi long khí suy yếu ở sát tường thành, Thạch Hạo dừng bước sau một kiếm cuối cùng, còn chiến tích thiếu niên Nhân Hoàng đánh bại Tôn giả khiến dân chúng Thạch đô sục sôi, uy danh và bảo ấn của hắn càng thêm lớn mạnh. Trở về hoàng cung, hắn cùng Chiến vương và Bằng Cửu dùng tổ tế đàn theo dõi đạo cô dẫn môn đồ tới kiếp thổ điều tra tung tích Nguyệt Thiền. Không ngờ nơi ấy đã được Thạch Hạo bố trí sát cục, đại trận vừa phát động liền xóa sổ các đệ tử, sau đó luyện chết cả thân thể lẫn nguyên thần của vị Tôn giả đang trọng thương, khiến lời đoán sinh tử của hắn hoàn toàn ứng nghiệm. Thạch Hạo tiếp tục tới hiện trường xóa dấu vết và hoàn thiện cạm bẫy chuyên nhằm vào Tôn giả, bảo đảm người bình thường không vô tình kích hoạt. Khi tin báo nhiều Tôn giả của ba giáo đang áp sát Thạch đô truyền tới, Chiến vương và Bằng Cửu đầy lo ngại, còn Thạch Hạo lại bình thản chờ họ tiến vào đại trận hoàng cung đã được cải tạo, thậm chí mong kẻ địch kéo đến càng đông càng tốt."},{"chuong":471,"tieuDe":"Gió Thổi Báo Giông Tố Sắp Tới","tomTat":"Tọa trấn Trung ương Thiên cung, Thạch Hạo nhận được mật báo rằng một số hoàng tử và công chúa đã bí mật qua lại với thế lực vực ngoại, nhưng hắn quyết định chỉ trừng trị khi họ thực sự vượt quá giới hạn. Tại Bất Lão sơn, Tần Lĩnh cùng các Tôn giả thừa nhận khó lòng khống chế ý chí vô địch của hắn, vì vậy định để Bổ Thiên giáo và Tây Phương giáo dồn hắn vào đường cùng rồi mới ra tay cứu giúp, ép hắn nhận tổ quy tông và phục vụ mưu đồ của họ. Các thế lực này đồng thời chuẩn bị cường giả tiến vào hoàng cung, trong lúc tin tức về thiên kiêu và quý nữ Thượng giới sắp hạ xuống tám vực càng khiến sóng ngầm thêm dữ dội. Bát hoàng tử cùng Thập nhất công chúa, Thập ngũ hoàng tử và Thập thất hoàng tử lần lượt vào cung, ngoài mặt yết kiến tân Hoàng nhưng thực chất âm thầm dò xét những trận pháp thần linh còn hư hại. Được các đại giáo chống lưng, Bát hoàng tử công khai phủ nhận pháp chỉ truyền ngôi và gọi Thạch Hạo là ngụy Hoàng, song lập tức bị hắn vạch trần là kẻ cam tâm dâng quốc thổ cho ngoại nhân rồi uy hiếp đến mức hoảng sợ rút lui. Nhận rõ ba giáo đang lợi dụng lòng tham của hoàng tộc để nội ứng ngoại hợp, Thạch Hạo nắm Bảo ấn Nhân Hoàng, cùng Bằng Cửu và Chiến vương bố trí phòng thủ, sẵn sàng tiêu diệt mọi cường giả dám tiến vào hoàng cung."},{"chuong":472,"tieuDe":"Ức Người Quá Mức","tomTat":"Năm vị Tôn giả của Bổ Thiên giáo, Tây Phương giáo và Bất Lão sơn dẫn theo môn đồ áp sát Hoàng thành Thạch Quốc, dùng uy thế khủng khiếp đè ép quân thủ thành. Dù các chiến tướng đã kích hoạt đại trận thần linh và thiêu đốt bảo liệu để tăng cường phòng ngự, Tôn giả Tây Phương giáo vẫn dùng pháp khí cấp thần trấn áp phù văn, sau đó hóa ra sư tử vàng đánh nổ cửa thành. Quân Thạch Quốc không liều chết ngăn cản bởi họ đã nhận mật lệnh của Thạch Hạo, cố ý để đoàn người tiến sâu vào hoàng cung theo kế hoạch. Cho rằng phòng tuyến Thạch Quốc đã suy yếu và tàn đồ đại trận nằm trong tay mình, các Tôn giả cùng đệ tử ngang nhiên xâm nhập cấm địa hoàng tộc, chế nhạo tân Hoàng trước toàn Thạch đô. Thạch Hạo mặc chiến y vàng, cầm pháp kiếm thần linh và mang thần kích trấn quốc, xuất hiện trước trung ương Thiên cung để đối mặt với năm cường địch. Khi nhóm Tôn giả ép hắn quỳ xuống giao ngôi, Thạch Hạo dâng cao chiến khí và tuyên bố sẽ giết sạch mọi kẻ xâm nhập."},{"chuong":473,"tieuDe":"Nhẹ Nhàng Hạ Tôn Giả","tomTat":"Trong Hoàng cung Thạch Quốc, Thạch Hạo khoác chiến y vàng, cầm pháp kiếm một mình đối diện năm Tôn giả của ba giáo bất hủ. Trước những lời chế giễu và phủ nhận địa vị Nhân Hoàng, nó dùng uy thế khiến nhiều đệ tử thổ huyết, rồi dẫn động sức mạnh dưới lòng đất giết chết hai kẻ vẫn tiếp tục xúc phạm. Khi các Tôn giả hợp lực bảo vệ môn đồ và tìm cách áp chế, Thạch Hạo thản nhiên bước đi giữa những đóa sen vàng, đồng thời công khai xác nhận mình đã giết đạo cô trung niên của Bổ Thiên giáo. Tôn giả Bổ Thiên giáo nổi giận, thi triển kỳ lân đỏ giao chiến với kiếm quang mang long khí, sau đó cùng bốn người còn lại tạo thành đại thế vây ép Thạch Hạo. Thạch Hạo dùng pháp kiếm chém tan thế liên thủ rồi kích hoạt trận pháp thần linh trong hoàng cung, cô lập riêng Tôn giả Bổ Thiên giáo khỏi đồng bọn. Dưới vô số ký hiệu trận pháp áp chế, vị Tôn giả kiệt sức chống đỡ, còn Thạch Hạo ung dung tiến tới và vung pháp kiếm vàng chém rơi đầu lão."},{"chuong":474,"tieuDe":"Máu Nhuộm Hoàng Cung","tomTat":"Thạch Hạo chém đầu Tôn giả Bổ Thiên giáo ngay giữa hoàng cung, khiến bốn Tôn giả còn lại kinh hãi và vội tìm đường thoát thân. Một Tôn giả Bất Lão sơn thử dùng tàn đồ mở thông đạo nhưng thất bại vì đại trận thần linh đã được tu bổ, đảo đổi phương vị và hoàn toàn phong tỏa chiến trường. Trước những lời cảnh cáo về sự trả thù của các đại giáo, Thạch Hạo khẳng định họ phải trả giá cho âm mưu giết tân hoàng, rồi vận dụng long khí Hoàng đạo quét sạch toàn bộ môn đồ Bổ Thiên giáo. Hai Tôn giả Tây Phương giáo dùng pháp khí thần linh, pháp thân Kim cang và Hàng Ma xử phản kích, song bị Côn Bằng quyền đánh tan, sau đó cùng bị thần kích trấn quốc chém chết dù đã thiêu đốt thân thể để liều mạng. Hai Tôn giả Bất Lão sơn viện dẫn quan hệ máu mủ để cầu hòa, nhưng Thạch Hạo bác bỏ, lần lượt dùng trận pháp giam cầm và giao chiến để lĩnh hội tuyệt học của họ. Cuối cùng, hắn mở toàn bộ trận pháp phong tỏa mười phương, vung thần kích chém chết cả hai Tôn giả cuối cùng, khiến máu nhuộm đỏ hoàng cung. Chiến tích một mình giết năm Tôn giả khiến các đệ tử đứng xa run rẩy, có kẻ ngã quỵ khi nhìn Thạch Hạo sừng sững như một ma thần."},{"chuong":475,"tieuDe":"Quốc Sắc Thiên Hương","tomTat":"Sau khi năm vị Tôn giả tử trận, Thạch Hạo điều động quân đội và chiến xa hoàng tộc thanh tẩy Thạch đô, tiêu diệt hoặc bắt giữ toàn bộ nhân mã còn sót lại của ba giáo, qua đó củng cố uy thế của tân Nhân Hoàng. Trong bảo khố, hắn cấp vật liệu cho Đả Thần Thạch bố trí đại trận, đồng thời dùng thần liệu và quốc lực làm điều kiện thuyết phục Tiểu Tháp tạm đảm nhiệm vị trí Tế Linh của Thạch Quốc. Tiểu Tháp trở về Thạch thôn thăm dò ý định của Liễu Thần rồi nhận lời, khiến Thạch Hạo thêm tự tin đối phó biến cục sắp tới và hướng đến mục tiêu đánh lên Thượng giới. Sau vài ngày nghiên cứu pháp môn Toan Nghê, Thạch Hạo bị Bằng Cửu và Chiến Vương thúc giục lập phi nên gọi Nguyệt Thiền ra khỏi khối đồng thau, công khai coi Thánh Nữ Bổ Thiên giáo là thị nữ khiến hai trọng thần kinh hãi. Thiên Hồ tiên tử, cũng chính là Ma nữ, sau đó tới trung ương Thiên cung và nhận ra khí tức của Nguyệt Thiền, buộc Thạch Hạo phải cho hai người gặp mặt. Ma nữ liên tục lấy chuyện thành thân và sinh con để trêu chọc đối thủ, rồi bất ngờ áp sát động tay khiến Nguyệt Thiền biến sắc, vội vàng lùi tránh."},{"chuong":476,"tieuDe":"Tuyệt Đại Song Kiều","tomTat":"Ma nữ lợi dụng lúc tu vi của Nguyệt Thiền bị phong ấn để trêu chọc, khiến vị tiên tử vốn thanh cao phải đỏ mặt và lúng túng trước Thạch Hạo. Khi bị Thạch Hạo dò xét ý định và dọa giữ lại, nàng tiết lộ mình có thần phù phá giới làm đường lui, đồng thời từ chối đổi nó lấy ba loại thần liệu. Ma nữ cho biết Hỏa quốc, Mộc quốc và Kim Lang cổ quốc đều đã phân liệt dưới sự can dự của các đại giáo vực ngoại, chỉ có Thạch Quốc vẫn duy trì thống nhất. Nàng còn kể về dị biến phá hủy hoàng đô Hỏa quốc và móng vuốt khổng lồ xuất hiện gần hoàng đô Thạch Quốc, khiến Thạch Hạo nhận ra thần tàng chí tôn có thể là một sát cục thật giả đan xen nhằm vào các đại nhân vật. Dù Ma nữ khẳng định Tiệt Thiên giáo xuống hạ giới chỉ để đối đầu Bổ Thiên giáo và mời hắn cùng tiến vào Cung điện chí tôn tìm truyền thừa, Thạch Hạo vẫn giữ lòng cảnh giác, quyết định chờ đợi thêm vì nơi ấy có thể khiến cả Thần mất mạng. Ma nữ tiếp tục tiết lộ Nguyệt Thiền là con gái của một nhân vật Thượng giới có thân phận kinh người, rồi ép nàng dâng trà và phục dịch; Nguyệt Thiền thà xoa vai cho Thạch Hạo còn hơn khuất phục đối thủ, cuối cùng bước tới đứng đối diện Ma nữ trong thế giằng co."},{"chuong":477,"tieuDe":"Gặt Hái Thành Quả","tomTat":"Trong trúc viên hoàng cung, Nguyệt Thiền tạm thời chăm sóc Thạch Hạo vì tu vi bị phong bế và muốn đề phòng Ma nữ, đồng thời cảnh báo hắn không nên tin đối thủ của nàng. Thạch Hạo không hoàn toàn nghe theo, bởi Ma nữ từng giúp hắn, còn chính Nguyệt Thiền lại từng dẫn người vây công hắn. Muốn phá vỡ tâm cảnh thanh khiết và dáng vẻ cao cao tại thượng của nàng, hắn buông lời trêu ghẹo rồi cưỡng ép ôm hôn khiến nàng tức giận chống cự. Ma nữ bất ngờ xuất hiện, chế nhạo Nguyệt Thiền bị kéo xuống phàm trần và công bố kế hoạch bồi dưỡng Thạch Hạo thành cường giả, chờ sau đại kiếp quét sạch lực lượng Bổ Thiên giáo cùng Tây Phương giáo tại hạ giới. Nàng còn bí mật nhắc hắn rằng Nguyệt Thiền có chiến lực chân chính rất đáng sợ, có thể sở hữu thủ đoạn phá giới giữ mạng và đang nhắm tới pháp môn Côn Bằng hoặc bí mật trưởng thành của hắn. Sau khi nghe hai người lần lượt nói xấu và cảnh báo về nhau, Thạch Hạo nhận ra không thể hoàn toàn tin tưởng bất kỳ bên nào, nhưng vẫn muốn giữ Nguyệt Thiền bên cạnh và nảy ý định biến lời đùa cưới tiên tử thành sự thật."},{"chuong":478,"tieuDe":"Đại Nhân Vật Thượng Giới","tomTat":"Đại kiếp bất ngờ tái diễn khi quy tắc thiên địa xuất hiện sơ hở, tạo cơ hội cho những tồn tại cấm kỵ từ Thượng giới cưỡng ép vượt giới. Qua tổ tế đàn, Thạch Hạo, Tiểu Tháp và Liễu Thần chứng kiến một sinh linh hình người màu bạc cùng bóng người áo vàng đội vương miện lần lượt giáng xuống Hỏa quốc, phá nát núi sông rồi tiến vào phế tích hoàng đô. Nhiều sinh linh đáng sợ khác cũng hội tụ tại đây để tranh đoạt Thần tàng chí tôn, nhưng Liễu Thần xác nhận cảnh con rùa khổng lồ gánh Thần tàng chỉ là giả. Sát trận thứ ba hình thành từ thuở khai thiên được kích hoạt, khiến kiếm khí và hỗn độn bao phủ phế tích, thậm chí làm một tồn tại cấm kỵ đổ máu. Liễu Thần nhân đó tiết lộ Nguyên Thủy Chân Giải gồm bản thượng Thần Dẫn, bản trung Siêu Thoát có thể nằm trong cung điện Chí Tôn, cùng bản hạ chưa từng bị ai đoạt được, đồng thời khẳng định sự lĩnh ngộ của Thạch Hạo không có vấn đề. Cuối cùng, đại kích Thiên Hoang hợp nhất ba đoạn từ Bắc Hải lao vào chiến trường, khiến Liễu Thần nghi ngờ Côn Bằng vẫn còn sống, ngay sau đó một dòng máu bạc óng ánh bất ngờ phun lên từ lòng đất."},{"chuong":479,"tieuDe":"Cuộc Chiến Của Bá Chủ Thượng Giới","tomTat":"Tiểu Tháp xác nhận uy thế vừa thức tỉnh chỉ là tàn niệm Côn Bằng trong đại kích Thiên Hoang; thần binh phá nát phế tích rồi rời đi, còn sát trận thứ ba tiếp tục đánh trọng thương bóng người màu bạc dưới lòng đất. Qua tổ tế đàn, Thạch Hạo chứng kiến sát trận thứ năm biến những tồn tại cấm kỵ đến tranh đoạt thành vật hiến tế, hút máu thịt và thần lực của họ để khôi phục linh căn đệ nhất Thượng giới. Khi hai bá chủ phá trận đưa linh căn lên mặt đất, chủ nhân đạo chung, người khống chế khay Hỗn Độn và sinh linh trong tàn tháp đồng loạt nhập cuộc, khiến hàng trăm nghìn dặm núi sông hóa thành vùng đất chết. Một đóa hoa bất ngờ tách khỏi linh căn, lập tức bị nữ Trùng Đồng chờ sẵn trên chín tầng trời dùng thần thông giam giữ rồi mang theo phá giới bỏ trốn. Những bá chủ khác lập tức truy kích, nhưng thuyền giấy đen của cô gái thần bí xuất hiện, chặn bàn tay tím và phá tan các thần thông vượt giới; nhân lúc chiến trường đại loạn, Liễu Thần cùng Tiểu Tháp cũng rời tổ tế đàn để trực tiếp tham chiến. Mất khả năng theo dõi cuộc chiến, Thạch Hạo lại phát hiện một ông lão tóc xám có thể vô tình biến núi non thành tro và một bà lão mang sọt thuốc đang săn các cường giả như hái dược liệu. Hắn kinh hãi nhận ra con nhện bị bà lão bắt chính là Tôn giả của hồ Ma Linh, đồng thời hiểu rằng hạ giới đã bị xem như một vườn săn thuốc, trước khi bà lão tuyên bố nơi này đã bị hái sạch và phá giới tới bảy lao tù khác."},{"chuong":480,"tieuDe":"Thiên Địa Náo Loạn","tomTat":"Chứng kiến sức mạnh tuyệt đối của các bá chủ Thượng giới, Thạch Hạo nhận ra thiên phú và ngôi vị Nhân Hoàng vẫn không đủ để tự định đoạt vận mệnh, từ đó quyết chí siêu thoát và một ngày đánh lên Thượng giới. Đại kiếp nhanh chóng lan khắp tám vực khi những kẻ giáng lâm tùy ý săn bắt Tôn giả, thần linh cùng các sinh linh quý hiếm làm dược liệu hoặc linh vật. Bà lão mang sọt thuốc bắt một Cầu Long có huyết mạch Chân Long, sau đó xông vào Bất Lão sơn, phá tan nơi bế quan và thu đi nhiều lão tổ dù đại trận hộ sơn đã được kích hoạt. Đạo nhân sáu tay cũng dùng hồ lô thu phục các linh thú mạnh mẽ, rồi tiến vào Tây Phương giáo bắt đại Tôn giả, đoạt sen thần, vườn thuốc và thánh vật để thanh toán mối nhân quả cũ. Trượng Lục Kim Thân hiện thân ngăn cản, mở cầu vàng dẫn đạo nhân ra vực ngoại giao chiến nhằm tránh tịnh thổ bên dưới bị hủy diệt. Trong hoàng cung Thạch quốc, Thạch Hạo đứng suốt đêm chờ đợi, hiểu rằng kết quả trận chiến sẽ ảnh hưởng đến bố cục Thượng giới và tương lai của tám vực; đến khi bình minh ló rạng, khí tức ngột ngạt suy giảm, báo hiệu đại chiến sắp kết thúc."},{"chuong":481,"tieuDe":"Vấn Đề Và Quyết Định","tomTat":"Sau trận đại chiến kinh thiên ngoài vực ngoại, nhiều bá chủ Thượng giới đã chết hoặc trọng thương, khiến Hoang vực được tinh khí của họ bồi bổ nhưng vô số thiên thể cũng bị phá hủy. Tiểu Tháp mang thương tích trở về, thuật lại kết cục đại kiếp, cho biết Liễu Thần đã lên đường tìm kiếm một tạo hóa trong truyền thuyết, rồi tiến vào Thế giới hộp quý dưỡng thương. Ma nữ đến cảnh báo rằng trong biển ý thức của Nguyệt Thiền có thể phong ấn một thần niệm đặc biệt, dặn Thạch Hạo tạm thời không hành động quá mức trước khi nàng tìm được vật cần thiết. Thạch Hạo liền trêu chọc để thăm dò Nguyệt Thiền, khiến nàng mất đi vẻ bình tĩnh thường ngày và vội vàng rút lui. Sau đó, một vương hầu của Bổ Thiên giáo mang pháp chỉ tới hoàng cung, nhưng Thạch Hạo không chịu hành lễ tiếp nhận, còn thẳng tay chặn thần uy từ ấn ký Bất Lão sơn. Trước long khí và sát ý của hắn, vị sứ giả kinh hãi quỳ xuống, không dám phản kháng. Sau khi đọc kỹ pháp chỉ và cân nhắc, Thạch Hạo quyết định đích thân tới Bất Lão sơn để tìm cha mẹ."},{"chuong":482,"tieuDe":"Tìm Ba Mẹ","tomTat":"Nhớ lại tuổi thơ bị tước Chí Tôn cốt, phải xa cha mẹ từ khi mới một tuổi và lớn lên tại Thạch thôn, Thạch Hạo quyết định đến Bất Lão sơn tìm người thân mà không oán trách chuyện năm xưa. Cậu tỏ ra coi nhẹ pháp chỉ của Bất Lão sơn, giao phó việc triều chính cho Chiến vương và Bằng Cửu, đồng thời mang theo Nguyệt Thiền đang bị trấn áp để đề phòng biến cố. Trên đường tới Hỏa quốc, Thạch Hạo tự dùng thần lực thúc đẩy thuyền phá không vượt xa giới hạn, khiến pháp khí này gần như tan nát sau khi vượt qua mấy triệu dặm. Từ một tòa thành do Bất Lão sơn quản lý, cậu cùng Tần Minh sử dụng trận pháp vượt vực, xuyên qua thông đạo màu bạc để rời Hoang vực và đặt chân lên Huyền vực. Tại vùng đất mới tràn đầy linh khí, Thạch Hạo mong sớm gặp lại cha mẹ và tìm được tung tích của ông nội Thập Ngũ gia, nhưng thân phận của cậu nhanh chóng bị những người canh giữ đạo đài nhận ra. Khi cự thuyền của Bất Lão sơn vừa tới đón hai người, đạo đài bất ngờ náo động vì có người từ Thượng giới giáng xuống Huyền vực, khiến Tần Minh vô cùng kinh hãi."},{"chuong":483,"tieuDe":"Tinh Anh Của Thượng Giới","tomTat":"Một nhóm quý nữ và anh tài trẻ tuổi từ các đạo thống thượng giới được đưa xuống Huyền vực, được các giáo phái long trọng nghênh đón và nhường khoang chính trên pháp thuyền để du ngoạn hạ giới. Vì phòng khách quý đã bị họ chiếm hết, Tần Minh định đưa Thạch Hạo xuống khoang đáy, nhưng bị nó chế giễu uy thế Bất Lão sơn nên đành nhờ thuyền trưởng thu xếp một phòng ở tầng cao nhất. Trước sự thù địch của hơn mười cường giả Bất Lão sơn, Thạch Hạo mở mười Động thiên áp chế tất cả, sau đó dò xét thần hồn họ để tìm tin về cha mẹ, ông nội và tình hình Bất Lão sơn, song không thu được manh mối mới. Dao động từ mười Động thiên khiến Lam tiên tử cùng các tinh anh thượng giới ở khoang bên cạnh nhận ra hạ giới vẫn có một kỳ tài đáng chú ý. Sáu, bảy người sang bái phỏng và đều kinh ngạc trước thực lực cùng tiềm năng chưa khai phá hết của Thạch Hạo. Khi biết nó mới mười lăm tuổi, các thiếu nữ càng sửng sốt rồi vui vẻ trêu Lam tiên tử rằng nàng có thể muốn ở lại hạ giới."},{"chuong":484,"tieuDe":"Thiên Địa Có Khuyết","tomTat":"Trong khoang khách quý, Thạch Hạo làm quen với Lam Vũ, Thủy Nguyệt, Hồng Hoàng và nhóm thiên kiêu thượng giới, khiến họ kinh ngạc vì mới mười lăm tuổi đã đạt thành tựu nổi bật ở Liệt Trận cảnh. Hồng Hoàng nhân màn trêu đùa chuyện kết duyên mà ra tay thăm dò, dùng phượng hoàng lửa công kích, còn Thạch Hạo bình tĩnh thi triển Chu Tước đối kháng rồi cùng nàng thu tay đúng lúc. Qua cuộc trò chuyện, Thạch Hạo biết tám vực hạ giới thực chất là những nhà giam do cường giả thời cổ luyện thành, có pháp tắc không trọn vẹn, đại đạo thiếu hụt, ngay cả phần lớn tinh tú cũng chỉ là vật được cô đọng hoặc hình chiếu từ thượng giới. Mọi người còn cho biết cư dân hạ giới muốn vượt Thiên môn phải chịu thẩm tra căn nguyên nghiêm ngặt, đặc biệt tán tu như Thạch Hạo sẽ gặp trở ngại rất lớn vì nơi đây từng giam giữ nhiều đại hung. Khi biết nó không thuộc Bất Lão sơn, Tây Phương giáo, Bổ Thiên giáo hay bất kỳ đạo thống nào, một số thiên kiêu lập tức trở nên hờ hững vì cho rằng tài năng ấy rồi sẽ mai một trong thiên địa thiếu khuyết. Trái lại, Tuyên Minh đề nghị Thạch Hạo gia nhập bộ tộc mình để được Huyền tổ giúp vượt Thiên môn và tiến vào Thánh viện thượng cổ, nhưng Oánh Oánh nghi ngờ y muốn thu nó làm chiến phó. Thủy Nguyệt cũng chủ động đưa ra lời mời, còn Lam Vũ khuyên Thạch Hạo cân nhắc kỹ giữa vô số lựa chọn của thượng giới mênh mông."},{"chuong":485,"tieuDe":"Giá Lâm Bất Lão Sơn","tomTat":"Trước khi chia tay nhóm thiên tài thượng giới, Thạch Hạo khéo léo né tránh những câu hỏi về quan hệ với Nguyệt Thiền và biết được nàng mang đạo thai hoàn mỹ, xuống hạ giới để tôi luyện trong thiên địa khiếm khuyết. Không vì xuất thân hạ giới mà nhụt chí, nó càng quyết tâm tiến vào thượng giới, còn nhóm Thủy Nguyệt tạm gác ý định theo tới Bất Lão sơn để tìm kiếm cơ duyên tại các mật địa khác. Sau năm ngày vượt hơn năm triệu dặm, Thạch Hạo đặt chân tới Bất Lão sơn, nhìn Ngũ Hành sơn hùng vĩ và nhớ tới cha mẹ cùng ông nội đang biệt tích. Sự xuất hiện của nó khiến cả thánh địa náo động, bởi nó từng đánh bại nhân mã nơi đây và giết hai Tôn giả. Huynh trưởng Tần Siêu cùng Tần Thủ Thành dẫn người chặn tại sơn môn, nhắc lại thù cũ rồi lợi dụng quy củ để ép nó quỳ bái Bất Lão Thiên tôn. Thạch Hạo thẳng thừng từ chối, sau đó lấy ra pháp chỉ có tổ ấn của lão tổ Thần linh và đảo ngược tình thế, buộc chính đám người Bất Lão sơn phải quỳ xuống trước quyền uy mà họ tôn thờ."},{"chuong":486,"tieuDe":"Tần Gia","tomTat":"Tại sơn môn Bất Lão sơn, Thạch Hạo dùng pháp chỉ mang tổ ấn buộc Tần Lập, Tần Thủ Thành và đoàn người định hạ uy mình phải quỳ lạy trong nhục nhã. Được Tần Minh dẫn vào Thần Vương điện, nó bị Tần tộc cố ý bỏ mặc rồi cho người đến chế giễu, dụ dỗ ra tay để kích hoạt sát trận và mời Tôn giả trấn áp. Thạch Hạo bình tĩnh chờ đối phương tụ tập đông đủ mới giương pháp chỉ lần nữa, khiến đám người gây hấn lại phải quỳ hoặc uất ức rút lui. Khi tiếp tục bị trì hoãn, nó thản nhiên dùng tử tuyền quý giá vốn dành để chế thuốc làm nơi ngâm chân, buộc Tần Minh phải đưa mình đi gặp một vị lão tổ cấp Tôn giả. Vị lão tổ xác nhận cha mẹ Thạch Hạo vẫn bình an và đang tu luyện trong đạo lô bất hủ tại khe núi thuộc dãy Ngũ Hành, nơi chỉ những lão tổ thần linh mới có tư cách tiến vào. Dù khe núi phải hai ngày nữa mới mở, Thạch Hạo vẫn xúc động đứng bên ngoài gọi lớn cha mẹ."},{"chuong":487,"tieuDe":"Tiểu Thạch Tức Giận","tomTat":"Thạch Hạo đến khe núi Ngũ Hành, nơi được đại trận thần linh bảo vệ, nhưng chưa thể gặp cha mẹ vì Tần Pháp nói họ đang tu luyện một môn thần thông và không thể rời đi. Tần Pháp dụ nó ở lại để gieo Đạo thai hoàn mỹ, đồng thời đề nghị giao Thạch quốc cho người em trai mười ba tuổi có thiên tư tuyệt thế, khiến Thạch Hạo vừa đau lòng vì tình thân vừa nhận ra mưu đồ can thiệp hoàng quyền của Bất Lão sơn. Khi hỏi về ông nội, nó được báo rằng Thạch Trung Thiên đã lên thượng giới, song Trùng Đồng thượng cổ lại giúp nó phát hiện một lỗ tên trên vách núi rất giống dấu vết từ thần tiễn của ông. Thạch Hạo lập tức dò xét thức hải một thị nữ và biết rằng hai năm trước nơi đây từng xảy ra một trận chiến, từ đó càng tin ông nội đã bị Bất Lão sơn ức hiếp. Cơn giận bùng phát, nó mở thập đại Động thiên, dung hợp với chiến y bất diệt màu đen rồi giao chiến, chỉ trong lần va chạm đầu tiên đã đánh nổ một bên vai Tần Pháp. Bất chấp uy hiếp từ đại trận có thể diệt thần ma, Thạch Hạo tuyên bố sẽ xới tung Bất Lão sơn để đòi công đạo cho ông nội, khiến Tần Pháp nghi ngờ nó vẫn còn lá bài tẩy và sinh lòng bất an."},{"chuong":488,"tieuDe":"Kiếm Áp Tôn Giả","tomTat":"Thạch Hạo khoác chiến y màu đen, dùng quyền ấn đánh tan Song Giao Tiễn, xuyên thủng các sát trận hộ thể và khiến Tôn giả Tần Pháp hộc máu. Khi Tần Pháp phát động kiếm trận gồm ba trăm sáu mươi lăm ánh kiếm được tế luyện trong máu thịt suốt nhiều năm, Thạch Hạo lấy một giọt tinh huyết diễn hóa kiếm đạo cây cỏ, phá sạch kiếm trận và hủy luôn pháp môn trong cơ thể đối thủ. Tần Pháp phải dùng kim đan chữa thương, đồng thời thừa nhận kiếm đạo cùng tiềm lực của Thạch Hạo đủ để danh chấn thượng giới và có thể giúp nó bước vào cảnh giới Tôn giả trong vài năm. Không tin lời lão nói ông nội mình đã tới thượng giới, Thạch Hạo nổi giận, diễn hóa hàng chục cây cỏ mang kiếm khí và đánh trúng đối phương mười ba kiếm. Tần Pháp hy sinh mười ba trận pháp trong cơ thể để giữ mạng nhưng vẫn mất một tay, một chân, tổn thương bản nguyên và gần rơi khỏi cảnh giới Tôn giả. Thạch Hạo mở thập đại Động thiên, bắt sống Tần Pháp để tiếp tục tra hỏi, bất chấp chiến mâu đang nhắm vào mình từ phía sau. Người ngăn nó giết Tần Pháp là một thiếu niên mặc chiến y Thần linh màu bạc, có dung mạo khiến nó cảm thấy quen thuộc, và người ấy tự xưng là Tần Hạo."},{"chuong":489,"tieuDe":"Nổi Giận Đùng Đùng","tomTat":"Tại Bất Lão sơn, Thạch Hạo gặp thiếu niên ngân y Tần Hạo có dung mạo gợi nhớ đến cha mẹ mình, rồi dễ dàng áp đảo đối phương trong cuộc so đấu thân thể cùng cảnh giới. Biết Tần Hạo đã đoán ra thân phận mình nhưng vẫn chỉ chăm chú quyết đấu, Thạch Hạo tỏ ra bất mãn và dùng thần kích trấn quốc uy hiếp những người Tần tộc, song đại trận nơi đây đã dẫn động binh khí về phía Ngũ Hành sơn, buộc hắn phải thu lại. Tần Trạm xuất hiện và công khai chuyện từng đánh Thạch Trung Thiên trọng thương, khiến Thạch Hạo nổi giận, dung hợp Bất diệt kim thân để quyết chiến rửa nhục cho ông nội. Hai bên giao kích dữ dội suốt hàng trăm nghìn chiêu, đều bị thương và thổ huyết, nhưng Thạch Hạo càng đánh càng mạnh. Hắn vận dụng Côn Bằng bảo thuật, diễn hóa đại bàng vàng cùng cá đen thành hai khí Âm Dương hợp nhất, đánh tan thân thể Tần Trạm rồi tiếp tục nện lão vào vách đá. Khi hai vách núi bất ngờ tách ra để lộ một tiên cốc mênh mông, Thạch Hạo lập tức nhấc Tần Trạm đang trọng thương và mang lão tiến vào khe núi."},{"chuong":490,"tieuDe":"Âm Mưu Chiếm Đại Pháp","tomTat":"Thạch Hạo mang Tần Trạm vào Cốc thần, vừa truy hỏi tung tích ông nội vừa liên tục đánh gãy xương lão vì những lời khiêu khích và sỉ nhục Lão Thập Ngũ. Nhờ pháp thể bất lão cùng hơn trăm trận pháp khắc trong máu thịt, Tần Trạm không chết mà còn âm thầm mượn ngoại lực phá bỏ giam cầm thân thể, tạo ra huyết thanh năm màu để niết bàn và sao chép thần thông của Thạch Hạo. Nhìn thấu âm mưu, Thạch Hạo thi triển pháp môn Côn Bằng xuyên thủng kén niết bàn, đồng thời kích phát những ám lực đã cài vào cơ thể đối phương, khiến máu thịt giải thể, trận pháp tàn lụi và đạo hạnh của Tần Trạm bị hủy. Trong quá trình thăm dò huyết thanh thần thánh, Thạch Hạo thu lấy các ký hiệu ẩn giấu, lĩnh hội Ngũ hành niết bàn và nhận ra đây là một trong những truyền thừa trấn giáo mạnh nhất của Bất Lão sơn. Nó nhấc Tần Trạm lao sâu vào sơn cốc, bỏ xa hai ông lão truy đuổi, dần thu được pháp môn niết bàn hoàn chỉnh cùng một số truyền thừa hữu ích khác. Tiến vào tịnh thổ tràn đầy khí tức thần linh, Thạch Hạo bắt gặp một khu vực giống sân nhỏ năm xưa tại Võ Vương phủ, rồi xúc động nhận ra hai bóng người quen thuộc chính là cha mẹ mình."},{"chuong":491,"tieuDe":"Nhìn Thấy Thần Linh","tomTat":"Thạch Hạo xách Tần Trạm tiến sâu vào Cốc thần tìm cha mẹ, thoáng thấy hai bóng người thân thuộc nhưng không thể liên lạc vì trận pháp thần linh ngăn cách. Khi Tần Hạo và hai ông lão Bất Lão sơn liên thủ truy kích, nó thi triển Bốn kích Chu tước Thái cổ và dùng pháp kiếm thần linh màu vàng đẩy lui cả ba. Đúng lúc lão tổ Bất Lão sơn thức tỉnh và tỏa ra thần uy khắp sơn cốc, Thạch Hạo vẫn bình tĩnh tinh luyện toàn bộ dấu ấn trong huyết thanh thần thánh của Tần Trạm, đoạt được thiên hoàn chỉnh của cổ pháp niết bàn. Tần Trạm niết bàn thất bại, thân thể gần như tan nát rồi bị nó nhốt vào Động thiên làm tù binh. Theo đại lộ kim quang do lão tổ mở ra, Thạch Hạo bước vào một khu tịnh thổ và gặp vị Thần mang hình dáng chàng trai trẻ mặc chiến y hoàng kim, người bất ngờ đề nghị thu nó làm đồ đệ. Cùng lúc đó, tại một tịnh thổ khác, cha mẹ Thạch Hạo đều cảm ứng được đứa con ở Thạch quốc đã đến rất gần, nhưng hai bên vẫn chưa thể đoàn tụ vì trận pháp phong tỏa."},{"chuong":492,"tieuDe":"Thần","tomTat":"Dưới cổ thụ lưu dấu đạo tắc của các đời Thần linh, Thạch Hạo dần bình ổn tâm trạng rồi yêu cầu vị thần mặc chiến y hoàng kim cho mình gặp cha mẹ. Tần Vũ từ đại điện đồng lên tiếng ngăn cản, đồng thời vạch rõ Tần Nhất Phàm chỉ đang dùng hình chiếu từ thượng giới và đóng tế đàn để cắt đứt liên hệ giữa hai giới. Dù thân ảnh nhanh chóng mờ nhạt, Tần Nhất Phàm vẫn điều khiển bức tranh hoàng kim định cuốn Thạch Hạo đi, muốn nhận nó làm đệ tử và đưa lên thượng giới. Không chấp nhận để người khác quyết định con đường của mình, Thạch Hạo dùng pháp kiếm trấn quốc, Nhân Hoàng ấn và long khí hoàng đạo chống cự, đồng thời dứt khoát từ chối bái sư. Tần Vũ vận chuyển trận pháp, mượn sức mạnh từ Ngũ Hành sơn đã công nhận mình, buộc Tần Nhất Phàm thu bức tranh hộ thân rồi rút vào hư không. Sau đó, Tần Vũ tuyên bố muốn giữ Thạch Hạo ở lại Tần tộc vì nó đã giết hai Tôn giả của Bất Lão sơn, nhưng trước yêu cầu gặp cha mẹ của nó, gã lại mở trận pháp truyền tống nó vào trọng địa có năm hồ niết bàn để tu hành và tìm cơ hội lột xác trước."},{"chuong":493,"tieuDe":"Anh Linh","tomTat":"Tần Vũ đưa Tần Hạo vào đại trận, đồng thời bộc lộ ý đồ dùng chiến trường anh linh kéo thần hồn Thạch Hạo khỏi thể xác để năm hồ niết bàn sao chép pháp môn Côn Bằng và mọi bí mật của hắn. Giữa không gian thượng cổ âm khí ngập trời, Thạch Hạo bị hàng vạn anh linh vây công rồi mắc kẹt trong linh vực màu bạc, nhưng hắn vận dụng Nguyên thủy chân giải, cưỡng ép thần hồn trở về thân thể. Hắn tiếp tục dùng pháp kiếm trấn quốc của Thạch tộc xé nát linh vực, sau đó bộc phát tinh lực dương cương thiêu hủy hàng ngàn anh linh, khiến Tần Vũ và các Tôn giả kinh hãi trước tiềm lực vượt xa dự liệu. Không chịu dừng tay, Tần Vũ mở Hóa ma trận, rút chiến ý và pháp lực của Thạch Hạo để tạo ra một hóa thân đối chiến với Tần Hạo, qua đó ép hai anh em tương tàn. Nhận ra đối thủ là em trai, Thạch Hạo phẫn nộ tố cáo những thủ đoạn của Bất Lão sơn đối với ông nội, cha mẹ và chính mình, rồi công khai tuyên bố sẽ lật tung thế lực này. Cùng lúc đó, Thạch Tử Lăng cảm ứng được cả hai con trai, nhận dao găm từ thê tử và cắt thủng không gian trận pháp, mở ra một khe hở để hai vợ chồng nhìn thấy cuộc giao chiến bên trong."},{"chuong":494,"tieuDe":"Thấp Kém","tomTat":"Trong cơn thịnh nộ, tinh khí thần và chiến ý của Thạch Hạo bùng lên, giúp cậu chạm tới ý cảnh Thần đạo rồi chém nát bảo ấn do hai Tôn giả hợp lực điều khiển. Khi Tần Vũ dùng lôi pháp trấn áp, cậu phối hợp pháp kiếm bảo cốt với Bảo thuật Toan nghê để hấp thu sấm sét và phản kích. Cảm ứng được cha mẹ đang bị giam gần đó, Thạch Hạo cất tiếng gọi, còn vợ chồng Thạch Tử Lăng dùng dao găm Hư không thú mở khe nứt trận pháp và xúc động nhìn thấy con trai đã trưởng thành. Tần Vũ tiếp tục tung thần huyết nhằm luyện hóa cậu, nhưng Thạch Hạo vận chuyển Nguyên thủy chân giải, đánh thức Chí Tôn cốt và biến giọt máu ấy thành chất dinh dưỡng. Trước thần uy của Tần Vũ, Thạch Hạo hứa giao bảo khố Thạch quốc và tự gánh nhân quả để đổi lấy việc Tiểu Tháp phá hủy Bất Lão sơn. Tiểu Tháp chấp thuận, hiện ra bản thể và khóa chặt Tần Vũ, khiến vị thần hoảng sợ tự bạo pháp y rồi tháo chạy về phía Ngũ hành sơn. Nhờ sự kiềm chế của Tiểu Tháp, Thạch Hạo vung kiếm làm rách mặt, cắt tóc và chém mất một phần vành tai Tần Vũ, đồng thời kết tội chính vị thần yếu đuối này đã đẩy Bất Lão sơn đến họa diệt vong."},{"chuong":495,"tieuDe":"Hóa Thần","tomTat":"Thạch Hạo cầm pháp kiếm thần khí truy sát Tần Vũ ngay trong Bất Lão sơn, buộc vị thần này phải tháo chạy về phía Ngũ hành sơn vì kiêng sợ Tiểu Tháp. Pháp kiếm hóa thành Toan nghê vàng, giáng xuống lôi điện cấp Thần, còn lời nguyền nhằm hủy diệt thần hồn Thạch Hạo cũng bị Tiểu Tháp dễ dàng hóa giải. Khi Tần Vũ từ chối tiết lộ tung tích ông nội, Thạch Hạo được Tiểu Tháp hỗ trợ phá lớp thần lực hộ thể rồi chém đứt một cánh tay của gã. Tần Vũ hiến tế cánh tay bị chặt để thi triển thần thuật ngũ hành kèm nguyền rủa, nhưng Chí tôn cốt trong ngực Thạch Hạo thức động, hiện ra hình người tí hon và luyện hóa toàn bộ tinh hoa thần tính. Dù thiêu đốt thần lực bỏ chạy, Tần Vũ vẫn bị bức tường phù văn không gian chặn khỏi Ngũ hành sơn, trong khi những người Bất Lão sơn chỉ có thể kinh hãi đứng nhìn. Bị dồn vào đường cùng, gã thừa nhận ông nội Thạch Hạo vẫn còn sống nhưng tiếp tục giấu nơi giam giữ, khiến Thạch Hạo nổi giận chém lìa cánh tay còn lại. Tinh hoa từ cánh tay thứ hai tiếp tục bị Chí tôn cốt hấp thu, khiến Tần Vũ phải chịu nỗi nhục trở thành nguồn dưỡng chất cho bảo cốt của một phàm nhân."},{"chuong":496,"tieuDe":"Ngũ Hành Sơn","tomTat":"Sau khi hấp thu thần tính còn lại từ cánh tay Tần Vũ, Chí tôn cốt trong ngực Thạch Hạo tiếp tục niết bàn, tự diễn hóa phù văn và tiến gần tới trạng thái hoàn chỉnh. Qua một khe hư không thoáng mở, cha mẹ cậu xúc động nhận ra Hạo nhi năm xưa nay đã trưởng thành đến mức có thể cầm kiếm đối đầu Thần linh, nhưng chưa kịp đoàn tụ thì khe nứt đã khép lại. Thạch Hạo ép hỏi tung tích Đại Ma Thần, biết ông nội cùng A Man đã thông qua trận pháp của Bất Lão sơn tiến vào thượng giới, rồi giết Tần Trạm và Tần Pháp để trả món nợ họ từng làm ông mình trọng thương. Tần Vũ thiêu đốt bản thân hiến tế, đánh thức Huyền tổ Tần Húc cùng ý chí của Ngũ hành sơn, song Thạch Hạo vẫn bất chấp lời ngăn cản, dùng kiếm khí hỗn độn chém gã thành sương máu và để Chí tôn cốt hấp thu tinh khí bản nguyên. Tiểu Tháp đứng ra che chở Thạch Hạo, nhắc lại nhân quả từ trận chiến năm xưa rồi trực tiếp giao phong với Ngũ hành sơn. Cú va chạm kinh thiên khiến thần sơn lệch khỏi vị trí trấn áp, để lộ một sinh linh gầy gò, tóc tai rối bời đang bị xích thần ngũ hành trói buộc, làm toàn bộ Tần tộc kinh hãi vì kẻ ấy tuyệt đối không thể xuất thế."},{"chuong":497,"tieuDe":"Sinh Linh Bất Diệt","tomTat":"Dưới Ngũ Hành sơn, một sinh linh gầy trơ xương vẫn sống sót sau vô tận năm tháng, bất chấp xích thần và thủ đoạn luyện hóa đạo cốt, chân hồn của Tần tộc. Khi Ngũ Hành sơn hiện ra bản thể hỗn độn để trở lại vị trí trấn áp, Tiểu Tháp đã dùng kiếm mang hỗn độn cùng dấu ấn vạn vật chân linh ngăn cản, khiến hai pháp khí liên tục va chạm bằng pháp tắc đại đạo. Muốn xác nhận tù nhân còn sống hay không, Tiểu Tháp chém xuống một kiếm, nhưng chỉ cắt đứt được một sợi tóc của hắn. Bất chấp lời cảnh báo rằng giải thoát sinh linh này sẽ gây họa lớn và đắc tội với những kẻ từng tham gia cuộc trấn áp năm xưa, Tiểu Tháp vẫn tiếp tục công kích để đánh thức hắn. Sinh linh bất diệt cuối cùng tỉnh lại, để lộ việc đã dùng bí pháp khóa chặt tinh khí nhằm giảm hao tổn và chống lại sự bào mòn của thời gian. Hắn đứng dậy giữa những sợi xích, mở đôi mắt vàng khiến người Tần tộc bị thương, rồi điên cuồng hút tinh khí thiên địa, tinh hoa nhật nguyệt và ánh sao vực ngoại để khôi phục nguyên khí. Các bá chủ cổ giáo cảm nhận được động tĩnh kinh thiên, nhận ra một nhân vật cái thế đã thoát vây và dự báo trời đất sắp xuất hiện biến cố lớn."},{"chuong":498,"tieuDe":"Nhân Quả Các Loại Cứ Đẩy Lên Người Ta","tomTat":"Sinh linh bất diệt vừa thoát khốn đã thu nạp bản nguyên thiên địa và tinh lực khắp Huyền vực, khiến sao trời hiện giữa ban ngày và khí thế của hắn nhanh chóng khôi phục. Tiểu Tháp liên tục đối đầu Ngũ hành sơn để tranh thủ thời gian cho hắn kéo căng xích thần, công kích tế đàn đỏ sậm và phá vỡ hệ thống trấn phong. Quan sát sinh linh ấy dùng thân thể, pháp lực và pháp tắc ngoại giới chống lại chí bảo hỗn độn, Thạch Hạo nhìn thấy phương hướng tu luyện đưa thân thể đến cực hạn, dù chưa lĩnh hội được pháp môn cụ thể. Khi cục diện không còn quá bất lợi, Tiểu Tháp chủ động rút khỏi chiến trường để bảo toàn pháp lực, để sinh linh bất diệt tự hiển hóa đôi cánh vàng khổng lồ chống đỡ sức trấn áp của Ngũ hành sơn. Nhân lúc hai bên giằng co, Tiểu Tháp đề nghị đột nhập bảo khố Bất Lão sơn và đẩy mọi nhân quả sang Thạch Hạo. Thạch Hạo chấp nhận gánh lấy hậu quả, nhưng kiên quyết phải cứu cha mẹ mình trước tiên."},{"chuong":499,"tieuDe":"Gặp Lại Ba Mẹ","tomTat":"Thạch Hạo quyết tâm tiến vào sơn cốc giam giữ cha mẹ, được Tiểu Tháp phá mở trận pháp thần linh bất chấp sự ngăn cản của Ngũ Hành Sơn. Ở sâu trong trận, cậu nhìn thấy Thạch Tử Lăng và Tần Di Ninh đang dùng dao găm xương Hư Không Thú chém vào hư không tìm đường thoát, liền bật khóc gọi cha mẹ. Sau hơn mười năm xa cách, một nhà ba người ôm chặt lấy nhau trong niềm vui đoàn tụ, còn Thạch Hạo khẳng định cậu chưa từng oán trách mà chỉ luôn thương nhớ song thân. Tần Di Ninh kể rằng hai vợ chồng từng đến Bất Lão Sơn cầu thuốc cứu con nhưng bị giam lỏng vì tranh đấu nội bộ Tần tộc và vì Chí Tôn cốt của Thạch Hạo. Tần tộc thượng giới còn đưa Thiên cốt cùng bảo dược xuống, dụ họ sinh người con thứ hai để thực hiện kế hoạch Chí tôn niết bàn, rồi nuốt lời không cho họ trở về. Mãi đến khi Tần Di Ninh lấy cái chết ép buộc, họ mới được đưa về Thạch thôn, nhưng nơi ấy đã hóa thành phế tích nên đành tuyệt vọng tin rằng con mình không còn sống. Nghe đến đây, Thạch Hạo rơi lệ và hiểu rằng cảnh hoang tàn năm đó là hậu quả từ cuộc tranh đoạt sơn bảo giữa Thôn Thiên Tước và Cùng Kỳ."},{"chuong":500,"tieuDe":"Đoàn Tụ","tomTat":"Thạch Hạo cuối cùng đoàn tụ với Thạch Tử Lăng và Tần Di Ninh, đồng thời biết Tần Hạo là em ruột được sinh ra sau khi cha mẹ từng tuyệt vọng cho rằng nó đã chết. Hai người giải thích rằng Tần tộc đã gieo vào Tần Hạo nỗi ám ảnh mình chỉ là kẻ thay thế, được nuôi dưỡng để dùng tinh huyết cứu anh trai, nên Thạch Hạo chủ động gạt bỏ hiềm khích và hứa bảo vệ em. Cha mẹ nó còn tiết lộ Bất Lão sơn từng âm thầm can dự vào quá trình trưởng thành của Thạch Nghị, mưu đoạt bảo cốt và chân thân của hắn nhưng thất bại trước cô gái áo xám bí ẩn. Từ khí tức Chí tôn trên tế đàn, Tiểu Tháp nghi ngờ Tần tộc đang chuẩn bị kế hoạch Chí tôn niết bàn nhằm tạo ra một thiếu niên Chí tôn với sự hỗ trợ của hai anh em. Thạch Hạo cũng hay tin Lão Thập Ngũ từng bị Tôn giả đánh trọng thương khi tìm cách giải cứu con trai, sau đó được Tần Hạo giúp cùng A Man bước vào cổ truyền tống trận và ngoài ý muốn tiến lên thượng giới. Dù đã được anh trai thừa nhận, Tần Hạo vẫn hiếu thắng và tuyên bố sẽ trở thành người mạnh nhất thiên hạ, còn Thạch Hạo chỉ ôn hòa nhường nhịn em. Giữa lúc sinh linh bất diệt cánh vàng chống lại Ngũ Hành Sơn, một luồng khí tức khủng bố chấn động Bất Lão sơn và lan khắp Huyền vực, khiến Tiểu Tháp nhận ra Bất Lão Thiên Tôn đang cưỡng ép hạ giới."}];
